def _enable_ansi() -> bool:
    """Whether escape sequences reach the terminal as colour and redraws.

    Windows 10 consoles interpret them once virtual terminal processing is
    switched on. Older ones print them raw, so the answer is then no.
    """
    if os.name != "nt":
        return True
    try:
        import ctypes  # noqa: PLC0415

        kernel32 = ctypes.windll.kernel32  # type: ignore[attr-defined]
        handle = kernel32.GetStdHandle(-11)
        mode = ctypes.c_uint32()
        if not kernel32.GetConsoleMode(handle, ctypes.byref(mode)):
            return False
        return bool(kernel32.SetConsoleMode(handle, mode.value | 0x0004))
    except (AttributeError, OSError):
        return False


# The roles text is painted with, from the 16 basic colours only: a
# handheld's Linux console has no more. The screens and the line questions
# name a role, never a code. Magenta is the hue that stays legible on black
# and on white in the xterm, VGA, Tango and Campbell palettes, so it is the
# accent, bold. Yellow reads poorly on white: it paints a status word, never
# a sentence. Bold red is bright red on the Linux console, where plain red on
# black is the weakest pair.
COLOUR_ROLES = {
    "accent": "1;35",
    "success": "32",
    "warning": "33",
    "failure": "1;31",
    "muted": "2",
    "strong": "1",
    # The accent reversed: the row in focus, its > kept for no colour.
    "selected": "7;35",
}

# The words a status takes its role from, wherever it is said. A count of
# zero is no news and stays plain: "0 missing" is not a warning.
_STATUS_WORDS = tuple((re.compile(pattern), role) for pattern, role in (
    (r"(?<!of )\b[1-9][\d,]* (?:files? )?(?:installed|in place|already in place"
     r"|ok|copied|downloaded)\b|\bDone\b|\bEvery file on the list is in place\b|^ *ok\b", "success"),
    (r"(?<!of )\b[1-9][\d,]* (?:files? )?(?:failed|refused)\b|\bFAILED\b|\bfailed:"
     r"|\bFinished with errors\b|\bNothing was installed\b|\bSomething went wrong\b",
     "failure"),
    (r"(?<!of )\b[1-9][\d,]* (?:files? )?(?:(?:still )?missing|wrong cop(?:y|ies)|not fetched"
     r"|left out|not downloaded)\b|\bFinished with files missing\b|\bNothing installed\b"
     r"|\bStopped\b|\bLeft out\b|\bNot enough space\b", "warning"),
))


def _apart(spans: list[tuple[int, int, str]]) -> list[tuple[int, int, str]]:
    """The spans in order, none empty, the longer kept where two overlap."""
    kept: list[tuple[int, int, str]] = []
    for span in sorted(spans, key=lambda span: (span[0], -span[1])):
        if span[1] > span[0] and (not kept or span[0] >= kept[-1][1]):
            kept.append(span)
    return kept


def status_spans(text: str) -> list[tuple[int, int, str]]:
    """(start, end, role) of the status words in text, in order, apart."""
    return _apart([(match.start(), match.end(), role) for pattern, role in _STATUS_WORDS
                   for match in pattern.finditer(text)])


def _sgr(role: str) -> str:
    """The SGR sequence of a role, or of roles joined by + ("strong+success")."""
    return "\033[0;" + ";".join(COLOUR_ROLES[name] for name in role.split("+")) + "m"


def painted(text: str, spans: list[tuple[int, int, str]], base: str = "") -> str:
    """text with each span in its role and the rest in the base role, a code
    written where the role changes and the colours reset at the end. The
    characters are those of text, in the same order. A span in "plain"
    takes the terminal's own colours."""
    pieces: list[tuple[str, str]] = []
    at = 0
    for start, end, role in spans:
        pieces += [(text[at:start], base), (text[start:end], role)]
        at = end
    pieces.append((text[at:], base))
    out: list[str] = []
    current = ""
    for piece, role in pieces:
        role = "" if role == "plain" else role
        if not piece:
            continue
        if role != current:
            out.append(_sgr(role) if role else "\033[0m")
            current = role
        out.append(piece)
    if current:
        out.append("\033[0m")
    return "".join(out)


_SGR = re.compile(r"\x1b\[[0-9;]*m")


def unpainted(text: str) -> str:
    """text without its SGR codes."""
    return _SGR.sub("", text)


class Terminal:
    """What the output stream can show: a live line, colour, or neither.

    A pipe or a log gets plain lines, and NO_COLOR and TERM=dumb or unset are
    honoured, as is a terminal whose description moves no cursor the ANSI way
    (vt52), or names fewer than 8 colours (vt100), which keeps the line live
    and plain.
    As no-color.org reads it, an empty NO_COLOR is not set: `NO_COLOR= cmd`
    turned colour off. FORCE_COLOR or CLICOLOR_FORCE paints a pipe, for a
    log viewer that shows colour, and never makes the line live.
    """

    def __init__(self, stream: TextIO | None = None, quiet: bool = False) -> None:
        self.stream = stream or sys.stdout
        self.quiet = quiet
        isatty = getattr(self.stream, "isatty", None)
        # An unset TERM is a dumb one, as the full screen reads it. A Windows
        # console sets none and draws the sequences once _enable_ansi is on.
        term = os.environ.get("TERM", "")
        self.live = (bool(isatty and isatty()) and term != "dumb"
                     and (bool(term) or os.name == "nt")
                     and not terminal_without_ansi(os.environ))
        forced = any(os.environ.get(name, "0") not in ("", "0")
                     for name in ("FORCE_COLOR", "CLICOLOR_FORCE"))
        self.colour = (
            ((self.live and not terminal_few_colours(os.environ)) or forced)
            and not os.environ.get("NO_COLOR") and _enable_ansi()
        )
        if not self.colour:
            self.live = self.live and os.name != "nt"

    def paint(self, text: str, role: str) -> str:
        return f"\033[{COLOUR_ROLES[role]}m{text}\033[0m" if self.colour else text

    def status(self, text: str) -> str:
        """text with its status words in their roles (status_spans)."""
        return painted(text, status_spans(text)) if self.colour else text

    def ok(self, text: str) -> str:
        return self.paint(text, "success")

    def bad(self, text: str) -> str:
        return self.paint(text, "failure")

    def dim(self, text: str) -> str:
        return self.paint(text, "muted")

    def bold(self, text: str) -> str:
        return self.paint(text, "strong")


class _Output:
    """What a run's text says. By default: what will happen, where, the
    progress, the result and the next step. --verbose adds every step, list
    and reason, the lines a beginner lost the result among. where_said is
    set once the BIOS folder was named before the result."""

    verbose = False
    where_said = False


OUTPUT = _Output()


def detail(*args: Any, **kwargs: Any) -> None:
    """Print a line only --verbose shows."""
    if OUTPUT.verbose:
        print(*args, **kwargs)


def format_duration(seconds: float) -> str:
    """0:42, 3:05 or 1:02:09."""
    seconds = max(0, int(seconds + 0.5))
    hours, rest = divmod(seconds, 3600)
    minutes, secs = divmod(rest, 60)
    return f"{hours}:{minutes:02}:{secs:02}" if hours else f"{minutes}:{secs:02}"


# The fewest columns a line question lays itself out in: below it a row is
# all number, and the terminal folds what is printed whatever it is.
LINE_MIN_COLS = 20


def terminal_size() -> tuple[int, int]:
    """(columns, lines) of the terminal line mode prints to, the one reading
    every layout of it makes. Python 3.8 gives a pty of no size as 0 and 0,
    where 3.11 falls back to 80 and 24: a list laid out in 0 columns never
    ended, the plan printed an empty heading, and the progress line lost
    every figure but its percentage."""
    size = shutil.get_terminal_size((80, 24))
    return max(size.columns or 80, LINE_MIN_COLS), size.lines or 24


class Progress:
    """Bytes and files across the parallel downloads, shown as they move.

    On a terminal one line redraws in place: a bar, the bytes, the speed and
    the time left. Elsewhere each finished file gets its line with --verbose,
    as a log wants it. Failures are always printed, quiet or not.
    """

    BAR = 24

    def __init__(self, total_files: int, total_bytes: int, term: Terminal,
                 events: bool = True) -> None:
        self.total_files = total_files
        self.expected_bytes = total_bytes
        self.total_bytes = max(total_bytes, 1)
        self.term = term
        self.files = 0
        self.bytes = 0
        self.resumed = 0
        # Bytes that came from this machine and not the network: a copy
        # found here, the pack, a resumed partial copy.
        self.local = 0
        # Files written to their place, which a stopped run counts: the
        # queue's length said "118 files installed" over 8 on disk.
        self.installed = 0
        # The entries of those files, which the end of the run counts apart.
        self.landed: list[dict] = []
        self.start = time.monotonic()
        self._drawn = 0.0
        self._evented = self.start
        self._lock = threading.Lock()
        # A data tree's archive draws the line and writes no event: the
        # progress events count the files of the download event.
        self.events = events

    def expect(self, total_bytes: int) -> None:
        """The size the transfer turns out to have, once its server says it."""
        with self._lock:
            self.expected_bytes = total_bytes
            self.total_bytes = max(total_bytes, 1)

    def add(self, count: int, resumed: bool = False, network: bool | None = None) -> None:
        """count bytes written, resumed ones left out of the speed. network
        is whether they came over the network, by default unless resumed."""
        with self._lock:
            self.bytes += count
            if resumed:
                self.resumed += count
            fetched = not resumed if network is None else network
            if not fetched:
                self.local += count
            now = time.monotonic()
            if self.term.live and not self.term.quiet and now - self._drawn >= 0.1:
                self._drawn = now
                self._draw()
            if self.events and EVENTS.on and now - self._evented >= EVENT_PROGRESS_INTERVAL:
                self._evented = now
                EVENTS.emit("progress", files_done=self.files, files_total=self.total_files,
                            bytes_done=self.bytes, bytes_total=self.expected_bytes)
                self.emit_transfer()

    def emit_transfer(self) -> None:
        """The transfer event: of the bytes done, those this machine held
        and those the network brought."""
        EVENTS.emit("transfer", bytes_local=self.local,
                    bytes_network=self.bytes - self.local)

    def forget_resumed(self, count: int) -> None:
        with self._lock:
            self.resumed -= count
            self.local -= count

    def transferred(self) -> int:
        """Bytes fetched by this run, a resumed partial copy excluded."""
        return self.bytes - self.resumed

    def done(self, dest: str, ok: bool, reason: str = "") -> None:
        with self._lock:
            self.files += 1
            line = None
            if not ok and not self.term.quiet:
                why = f" ({reason})" if reason else ""
                line = f"  {self.term.bad('FAILED')} {dest}{why}"
                SAID_FAILED.add(dest)
            elif not self.term.live and not self.term.quiet and OUTPUT.verbose:
                line = f"  [{self.files}/{self.total_files}] {dest} {self.term.ok('ok')}"
            if line is not None:
                self._clear()
                print(line, file=self.term.stream, flush=True)
            if self.term.live and not self.term.quiet:
                self._draw()

    def finish(self) -> None:
        with self._lock:
            self._clear()

    def elapsed(self) -> float:
        return time.monotonic() - self.start

    def _clear(self) -> None:
        if self.term.live and not self.term.quiet:
            print("\r\033[K", end="", file=self.term.stream, flush=True)

    def _draw(self) -> None:
        share = min(self.bytes / self.total_bytes, 1.0)
        elapsed = self.elapsed()
        # A resumed partial copy was on disk before the run started: counted
        # in the share, never in the speed.
        speed = self.transferred() / elapsed if elapsed > 0 else 0
        left = (self.total_bytes - self.bytes) / speed if speed > 0 else 0
        # Copies from a folder here count in no speed: "0 B/s  0:00 left"
        # was drawn under them, as the screen does not.
        timed = [f"{format_size(int(speed))}/s", f"{format_duration(left)} left"] \
            if self.transferred() > 0 else []
        parts = [
            f"{share * 100:5.1f}%",
            f"{format_size(self.bytes)} / {format_size(self.total_bytes)}",
            *timed,
            f"({self.files}/{self.total_files} files)",
        ]
        # One physical line, whatever the width: \r\033[K clears only the
        # line the cursor is on, so a wrapped line left a ghost per redraw
        # on an 80-column console. The bar gives way first, then the least
        # telling figures.
        width = terminal_size()[0] - 1
        while True:
            tail = "  ".join(parts)
            room = width - len(tail) - 6
            if room >= 10 or len(parts) == 1:
                break
            parts.pop()
        if room >= 10:
            bar_width = min(self.BAR, room)
            filled = int(share * bar_width)
            text = f"  [{'#' * filled}{'-' * (bar_width - filled)}] {tail}"
        else:
            text = f"  {tail}"
        print(f"\r\033[K{text[:width]}", end="", file=self.term.stream, flush=True)


# --events: one JSON object per line on stdout, for a program driving the
# installer (the handheld port shows its screens from them). Each kind has
# exactly these keys besides "event", in this order, and nothing else.
EVENT_SCHEMA = 1
EVENT_KEYS: dict[str, tuple[str, ...]] = {
    # mode: install, check, dry-run, list, remove (--remove, --delete-backup),
    # restore or pack (--pack, with --dry-run too).
    "start": ("schema", "installer", "mode"),
    # A folder detection could not look in, once each, before detect: the
    # probes under it counted as absent and the others went on. reason is
    # why in words (Permission denied). A kind of its own, since schema 1
    # never adds a key to detect, and not an error: the run goes on.
    "unsearched": ("folder", "reason", "message"),
    # platforms: [{"platform", "name", "bios_dir"}], empty when none is found.
    "detect": ("os", "os_name", "platforms"),
    # stage: manifest (reason: network, not_found, invalid, clock for a
    # refused certificate under a clock set in the past, no_ca for no
    # trusted certificates on the machine, or no_ssl for a Python built
    # without ssl) or detect (reason: conflict, two
    # systems found on one machine, or not_found, the platform named with
    # --platform, or by a file list or a pack in a run without questions,
    # found nowhere and no folder to assume) or from (a folder named with --from,
    # reason: not_found, not_a_folder, unreadable, or system for the root
    # of the system and /proc, /sys, /dev) or dest (reason: unreadable, a
    # folder above it this user cannot open, not_a_folder, the BIOS folder
    # is a file or lies under one, or not_writable, the BIOS folder cannot
    # be created, a summary following) or option (reason:
    # unknown, a platform, target, system, core or emulator the run cannot
    # use, refused before any download).
    "error": ("stage", "reason", "platform", "message"),
    # A folder named with --from, once read: the files it holds (counted
    # up to MAX_SCANNED_FILES, truncated past them), and the folders below
    # it on another drive, not entered.
    "scanned": ("folder", "files", "truncated", "other_drives"),
    # Before choices, once a list is read: the system here runs another
    # version than the one the list was built for (list_version, from the
    # manifest, installed_version, from the system's own version file).
    # message says it and what it means. Not written when either version
    # is unknown, and never a refusal.
    "version": ("platform", "list_version", "installed_version", "message"),
    # Before choices: the board the system or its card names, read with no
    # --target given. applied is whether the run keeps its cores' files
    # only, false for a board the platform's list does not name. message
    # says it. A kind of its own: the full-screen interface always gives
    # --dest, and the board was never applied there.
    "board": ("platform", "board", "applied", "message"),
    # --installed-cores, before choices, once per installed core the list
    # has no profile for: info is whether its .info was found, dests the
    # firmware paths it declares, kept whatever the narrowing drops. A
    # core with no .info keeps nothing it alone reads, and message says so.
    "unknown_core": ("platform", "core", "info", "dests", "message"),
    # Before the file events of a check: the systems the run's list lets
    # one choose among, --system aside, in id order (other for the files
    # no system names). What Choose systems lists, and what the plan counts
    # a --system out of: it said 12 where Choose systems listed 11. A kind
    # of its own, since schema 1 never adds a key to check.
    "choices": ("platform", "systems"),
    # Right after choices: the dests of the list's files the run sets aside
    # before any choice, those read from a save directory whose place is
    # not known among them, in list order. What Cores lists and counts is
    # the list without them: it listed 189 cores where --core accepted 181,
    # and an untick sent the 8 others to a run that refused them. A kind of
    # its own, since schema 1 never adds a key to choices.
    "set_aside": ("platform", "dests"),
    # state: present (hash verified), wrong_hash or missing.
    "file": ("platform", "dest", "systems", "size", "state"),
    "system": ("platform", "system", "name", "files", "present", "missing",
               "wrong_hash", "bytes_needed"),
    # The files in place being read, at most every half second, and the last.
    "checking": ("files_done", "files_total"),
    # --for-games: the games of the card being read (a cartridge hashed, a
    # disc's header read), at most every half second, and the last.
    "games_reading": ("files_done", "files_total"),
    # --for-games, once the games are read, before choices: the games
    # folder, the games found and those recognised by their content.
    # found: [{"system", "folder", "games", "recognised", "regions"}],
    # regions the ones kept where the games prove one, empty for every
    # region. fallback: [{"system", "folder", "name", "reason"}], each game
    # that got every BIOS of its system (reason: not_recognised, not_read,
    # region_unknown, unknown_set, no_parent). not_games: the other files
    # of the game folders. required_only: --required-only given.
    "games": ("platform", "folder", "games", "recognised", "found", "fallback",
              "not_games", "required_only"),
    # --for-games could not read what the games need (reason: offline,
    # network, invalid, stale, no_sets, no_folder): the run keeps every
    # file of the list, and message says why.
    "games_unavailable": ("platform", "reason", "message"),
    "check": ("platform", "name", "bios_dir", "files", "present", "missing",
              "wrong_hash", "bytes_needed", "data_missing", "not_installable"),
    # Right after check: the same counts over the files the platform's own
    # list declares (cores: null), and their dests in file-event order. A
    # kind of its own, since schema 1 never adds a key to the file event.
    "declared": ("platform", "files", "present", "missing", "wrong_hash",
                 "bytes_needed", "dests"),
    # Right after declared: the files of the data trees to fetch (check's
    # data_missing) and the bytes they write. A kind of its own, since
    # schema 1 never adds a key to check.
    "data": ("platform", "files", "bytes"),
    # A file to install that this machine already holds: misplaced in the
    # BIOS folder (folder is its bios_dir, reason says why in words) or in
    # a folder named with --from (reason empty). member names the ZIP member
    # when path is an archive, else "". Its copy is a downloaded event.
    "found": ("platform", "dest", "folder", "path", "member", "reason"),
    # What a folder named with --from holds that could not be read, of the
    # size of a file no copy was found for, or of no known size (a folder,
    # a ZIP that would not open). member as in found, reason in words.
    "unreadable": ("platform", "folder", "path", "member", "reason"),
    # The files of the list read from the frontend's save directory, and
    # where they go (<system> and <core> stand for a folder per system or
    # per core), once that directory is known. Not written when it is not:
    # the summary's skipped then counts them (no_save_directory).
    "saves": ("platform", "files", "folder"),
    "download": ("platform", "files", "bytes"),
    "progress": ("files_done", "files_total", "bytes_done", "bytes_total"),
    # Right after each progress event, and once when the files of a
    # download event are done: bytes_done split into the bytes this machine
    # held (a copy found here, the pack, a resumed partial copy) and the
    # bytes the network brought. A speed is bytes_network over time.
    "transfer": ("bytes_local", "bytes_network"),
    "downloaded": ("dest", "ok", "reason", "size", "files_done", "files_total",
                   "bytes_done", "bytes_total"),
    # failed: [{"dest", "reason"}]. skipped: [{"reason", "label", "files",
    # "required"}], the files the collection cannot supply. left_out:
    # [{"category", "label", "files", "dests"}], what --no-game-data left
    # out, empty without it. kept: [{"folder", "files", "bytes"}], the files
    # in place the run moved aside before replacing them (under --dry-run,
    # would move), one per backup folder, empty when none.
    "summary": ("mode", "installed", "up_to_date", "pending", "failed", "skipped",
                "left_out", "kept", "interrupted"),
    # --add-app, or yes to its question, after the summary: the RetroBIOS
    # app put on the handheld card (folder, its root) of system. dests are
    # the app's files below the root, written those this run wrote (none
    # when all were in place), kept the backup folders as in summary.
    # ok false with reason when it was refused or failed.
    "app": ("system", "folder", "ok", "reason", "dests", "written", "kept"),
    # The install record of the BIOS folder (path, beside it in
    # retrobios-backup). status: applied (before choices, its choice taken
    # as the run's because nothing on the command line chose), written
    # (before the summary, once the install placed files), unreadable (said
    # once and ignored) or not_written (the install itself unharmed). choice is
    # the recorded options as words, date when it was written, files the
    # files it holds for the platform. A kind of its own, since schema 1
    # never adds a key to an existing kind.
    "record": ("platform", "folder", "path", "status", "choice", "date", "files", "message"),
    # --remove, before anything is removed (with --dry-run, all it writes):
    # the files that go (dests, in record order), their bytes, the systems
    # losing a file, kept [{"dest", "reason"}] for each file left (reason
    # one of REMOVAL_REASONS), gone the recorded files no longer there,
    # backup whether they are moved rather than deleted. message says it.
    # Written with files 0 when no record says what is the installer's.
    "removal_plan": ("platform", "folder", "files", "bytes", "systems", "dests", "kept",
                     "gone", "backup", "message"),
    # Each file --remove took: ok false with reason when it stays, moved_to
    # the file's place in the backup with --backup, else "".
    "removed": ("platform", "dest", "size", "ok", "reason", "moved_to"),
    # Each file --restore put back from the backup folder to path.
    "restored": ("folder", "path", "size", "ok", "reason"),
    # A backup folder: listed by --backups, made by --remove --backup, or
    # deleted (not_deleted when a file stayed) by --delete-backup. date is
    # when it was made (local time), source remove for a removal's, install
    # for the files an install replaced.
    "backup": ("folder", "date", "files", "bytes", "source", "status", "message"),
    # --pack: planned (--dry-run), written or failed. files and bytes are
    # the pack's members, each stored once, size what it takes on disk,
    # parts each file written (the pack alone when it is one ZIP).
    "pack": ("platform", "path", "files", "bytes", "size", "parts", "status", "message"),
    "end": ("code",),
}
# Seconds between two progress events while bytes arrive.
EVENT_PROGRESS_INTERVAL = 0.5


class EventStream:
    """The --events output: closed (nothing written) until opened."""

    def __init__(self) -> None:
        self.stream: TextIO | None = None
        self._lock = threading.Lock()

    def open(self, stream: TextIO) -> None:
        self.stream = stream

    @property
    def on(self) -> bool:
        return self.stream is not None

    def emit(self, kind: str, **fields: object) -> None:
        if self.stream is None:
            return
        keys = EVENT_KEYS[kind]
        if set(fields) != set(keys):
            raise ValueError(f"event {kind}: keys {sorted(fields)} != {sorted(keys)}")
        # Every string a script reads goes through the terminal's filter,
        # a new line kept: a consumer printing a folder or a name obeyed
        # the control characters a card label or a list held.
        line = json.dumps({"event": kind, **{key: _clean_strings(fields[key], "\n")
                                             for key in keys}})
        with self._lock:
            self.stream.write(line + "\n")
            self.stream.flush()


EVENTS = EventStream()


def _event_mode(args: argparse.Namespace) -> str:
    if getattr(args, "remove", False) or getattr(args, "delete_backup", None) is not None:
        return "remove"
    if getattr(args, "restore", None) is not None:
        return "restore"
    if getattr(args, "backups", False):
        return "list"
    if getattr(args, "pack", None) is not None:
        return "pack"
    if args.check:
        return "check"
    if args.dry_run:
        return "dry-run"
    if (args.list_platforms or args.list_targets or args.list_systems
            or args.list_cores or args.list_emulators):
        return "list"
    return "install"


def _event_exit_code(code: object) -> int:
    """The process status sys.exit(code) gives."""
    if code is None:
        return 0
    return code if isinstance(code, int) else 1


def _os_name() -> str:
    """The OS's own name, from os-release, else the kernel's."""
    release = _parse_os_release()
    return release.get("PRETTY_NAME") or release.get("NAME") or platform.system()


def _emit_check(
    plat: str, manifest: dict, bios_path: Path, files: list[dict], up_to_date: list[dict],
    mismatched: list[dict], data_missing: int, not_installable: int,
    chosen: list[str] | None = None, data_bytes: int = 0,
) -> None:
    """One event per file, per system and per platform after a check, then
    one for the files of the platform's own list.

    With systems chosen, only those are described: a file of SkyEmu's
    carries four systems, and --system nintendo-gba described gb, gbc and
    ds by the few files the choice kept of them.
    """
    present = {id(entry) for entry in up_to_date}
    wrong = {id(entry) for entry in mismatched}
    systems: dict[str, dict[str, int]] = {}
    for entry in files:
        state = ("present" if id(entry) in present
                 else "wrong_hash" if id(entry) in wrong else "missing")
        size = entry.get("size", 0)
        EVENTS.emit("file", platform=plat, dest=entry["dest"],
                    systems=entry_systems(entry), size=size, state=state)
        for system in entry_systems(entry) or [OTHER_SYSTEMS]:
            counts = systems.setdefault(system, {
                "files": 0, "present": 0, "missing": 0, "wrong_hash": 0,
                "bytes_needed": 0,
            })
            counts["files"] += 1
            counts[state] += 1
            if state != "present":
                counts["bytes_needed"] += size
    names = manifest.get("system_names") or {}
    for system in sorted(systems):
        if chosen and system not in chosen:
            continue
        EVENTS.emit("system", platform=plat, system=system,
                    name=", ".join(names.get(system) or [system]), **systems[system])
    needed = [entry for entry in files if id(entry) not in present]
    EVENTS.emit(
        "check", platform=plat, name=display_name(plat, manifest), bios_dir=str(bios_path),
        files=len(files), present=len(up_to_date), missing=len(needed) - len(mismatched),
        wrong_hash=len(mismatched),
        bytes_needed=sum(entry.get("size", 0) for entry in needed),
        data_missing=data_missing, not_installable=not_installable,
    )
    # The copy the platform itself checks at each of its slots, which is
    # what --declared-only checks: a core's copy served in its place is
    # judged against the platform's.
    own_states = []
    for entry in files:
        if entry.get("cores") is not None:
            continue
        copy = declared_copy(entry)
        if copy is entry or copy.get("sha1") == entry.get("sha1"):
            state = ("present" if id(entry) in present
                     else "wrong_hash" if id(entry) in wrong else "missing")
        else:
            state = _declared_state(copy, entry, bios_path)
        own_states.append((entry["dest"], copy.get("size", 0), state))
    EVENTS.emit(
        "declared", platform=plat, files=len(own_states),
        present=sum(1 for _d, _s, state in own_states if state == "present"),
        missing=sum(1 for _d, _s, state in own_states if state == "missing"),
        wrong_hash=sum(1 for _d, _s, state in own_states if state == "wrong_hash"),
        bytes_needed=sum(size for _d, size, state in own_states if state != "present"),
        dests=[dest for dest, _s, _state in own_states],
    )
    EVENTS.emit("data", platform=plat, files=data_missing, bytes=data_bytes)


def _declared_state(copy: dict, entry: dict, bios_path: Path) -> str:
    """present, missing or wrong_hash: the file at entry's place against copy."""
    try:
        path = _entry_path(bios_path, entry)
    except ValueError:
        return "missing"
    try:
        if not path.is_file():
            return "missing" if not path.exists() else "wrong_hash"
        verdict = _classify_local(copy, path)
    except OSError:
        return "wrong_hash"
    return "present" if verdict == "up_to_date" else "wrong_hash"


def leave_out_game_data(
    files: list[dict], omitted: list[dict]
) -> tuple[list[dict], list[dict], list[dict]]:
    """The files and omissions without game data, and what was left out.

    The same cut as a pack built with --no-game-data: the manifest marks
    each file that is a game's data, not firmware.
    """
    left_out = [e for e in files + omitted if e.get("category") == GAME_DATA]
    return (
        [e for e in files if e.get("category") != GAME_DATA],
        [e for e in omitted if e.get("category") != GAME_DATA],
        left_out,
    )


class Tally(NamedTuple):
    """Files and bytes of one list, BIOS files and game data apart. bios
    and games add up to files, their bytes to size: every count a run
    prints of a list comes from here."""

    files: int
    size: int
    bios: int
    bios_size: int
    games: int
    game_size: int


def tally(entries: Iterable[dict]) -> Tally:
    """The counts of entries, each with its size and the category the list
    gives it, anything not game data being a BIOS file.

    The run said 8069 files (6.5 GB) while its menu said 8348 (7.1 GB) and
    3259 BIOS files and 5089 game data files: three counts of three lists.
    """
    bios = bios_size = games = game_size = 0
    for entry in entries:
        size = int(entry.get("size") or 0)
        if entry.get("category") == GAME_DATA:
            games += 1
            game_size += size
        else:
            bios += 1
            bios_size += size
    return Tally(bios + games, bios_size + game_size, bios, bios_size, games, game_size)


def sized_words(counts: Tally) -> str:
    """The count and the size, as in 8358 files, 6.6 GB."""
    return f"{_plural(counts.files, 'file')}, {format_size(counts.size)}"


def installed_words(bios: int, games: int, data: int = 0) -> str:
    """The kinds a run installed, those it installed none of left out:
    "6 BIOS files" where the old card's result said no kind at all."""
    parts = [_plural(count, word) for count, word in (
        (bios, "BIOS file"), (games, "game data file"), (data, "data file")) if count]
    if not parts:
        return _plural(0, "file")
    return f"{', '.join(parts[:-1])} and {parts[-1]}" if len(parts) > 1 else parts[0]


def parts_words(counts: Tally, data: int = 0, data_size: int | None = None,
                left_out: int = 0) -> str:
    """The files of a plan by kind, each with its size: BIOS files, game
    data and the data files of the emulators' data folders, then the game
    data left out. "" when one kind alone is counted and nothing is left
    out. "8358 files and 2636 data files" sat above "3269 BIOS files and
    5089 game data files", which add up to 8358 only, and "No game data"
    read as a list holding none."""
    parts = []
    if counts.bios or not (counts.games or data):
        parts.append(f"{_plural(counts.bios, 'BIOS file')} ({format_size(counts.bios_size)})")
    if counts.games:
        parts.append(f"{_plural(counts.games, 'game data file')} "
                     f"({format_size(counts.game_size)})")
    if data:
        parts.append(_plural(data, "data file")
                     + (f" ({format_size(data_size)})" if data_size is not None else ""))
    if len(parts) < 2 and not left_out:
        return ""
    text = f"{', '.join(parts[:-1])} and {parts[-1]}" if len(parts) > 1 else parts[0]
    return text + (f". {_plural(left_out, 'game data file')} left out" if left_out else "")


def kinds_definition(games: bool, data: bool) -> str:
    """What game data and data files are, one sentence each, for the kinds
    a plan counts: said once, after the counts."""
    said = [words[0].upper() + words[1:] + "." for words, shown in (
        (GAME_DATA_WORDS, games), (DATA_FILES_WORDS, data)) if shown]
    return " ".join(said)


def game_data_state(left_out: bool, games: Tally) -> str:
    """The one label of the game data choice, its count after: the plan's
    row and the line menu's g."""
    return (f"Game data: {'left out' if left_out else 'kept'} "
            f"({_plural(games.games, 'file')}, {format_size(games.game_size)})")


def keep_declared(files: list[dict], omitted: list[dict]) -> tuple[list[dict], list[dict]]:
    """The files and omissions the platform's own list declares (cores: null).

    A slot a core contradicts gets the platform's copy, and no core copy
    stays behind as an alternative: narrowing by cores afterwards would
    otherwise put a core's file back where a dropped system's was. Which of
    the platform's declarations answers is left to that narrowing, as
    without --declared-only: the first whose systems remain.
    """
    def own(entries: list[dict]) -> list[dict]:
        result = []
        for entry in entries:
            if entry.get("cores") is not None:
                continue
            kept = {k: v for k, v in _settle_slot(entry, set()).items()
                    if k not in ("alternatives", "declared_copy")}
            declared = entry.get("declared_choices") or []
            if len(declared) > 1:
                kept["declared_choices"] = declared
            result.append(kept)
        return result

    return own(files), own(omitted)


def declared_copy(entry: dict) -> dict:
    """The copy the platform's own list checks at a platform file's slot.

    A narrowing that serves a core's copy there records the platform's
    answer beside it, and an entry not yet settled answers by its first
    declaration. Otherwise the entry is the platform's copy itself.
    """
    recorded = entry.get("declared_copy")
    if recorded is not None:
        return recorded
    declared = entry.get("declared_choices")
    if declared:
        return declared[0]
    return entry


def _left_out_lines(left_out: list[dict], every: bool) -> list[str]:
    """What --no-game-data left out, named per category, ten each unless every."""
    lines = []
    # The omitted ones apart: "leave out the 5089 game data files" was
    # followed by "Left out as game data: 5099 files", the other ten being
    # files the list cannot install anyway.
    for group in _left_out_events(left_out):
        dests = group["dests"]
        shown = dests if every else dests[:10]
        more = (f" ... and {len(dests) - len(shown)} more (--verbose lists them all)"
                if len(shown) < len(dests) else "")
        omitted = sum(1 for entry in left_out if entry.get("reason")
                      and entry.get("category", "") == group["category"])
        aside = f", {omitted} of them not installable" if omitted else ""
        lines.append(f"  {left_out_words(group)} (--no-game-data){aside}: "
                     f"{', '.join(shown)}{more}")
    return lines


def left_out_words(group: dict) -> str:
    """A left_out group in the plan's words: 6 game data files left out."""
    return f"{_plural(group['files'], group['label'] + ' file')} left out"


def _left_out_events(left_out: list[dict]) -> list[dict]:
    """What --no-game-data left out, per category, every file named."""
    groups: dict[str, dict] = {}
    for entry in left_out:
        category = entry.get("category", "")
        group = groups.setdefault(category, {
            "category": category, "label": CATEGORY_LABELS.get(category, category),
            "files": 0, "dests": [],
        })
        group["files"] += 1
        group["dests"].append(entry["dest"])
    return [groups[category] for category in sorted(groups)]


def _skipped(omitted: list[dict]) -> list[dict]:
    """The files the collection cannot supply, grouped by reason."""
    groups: dict[str, dict] = {}
    for entry in omitted:
        reason = entry.get("reason", "unknown")
        group = groups.setdefault(reason, {
            "reason": reason, "label": OMISSION_REASONS.get(reason, reason),
            "files": 0, "required": 0,
        })
        group["files"] += 1
        group["required"] += bool(entry.get("required", True))
    return [groups[reason] for reason in sorted(groups)]


# The three RetroArch packages published for Android, newest ABI first.
ANDROID_RETROARCH_PACKAGES = (
    "com.retroarch.aarch64",
    "com.retroarch",
    "com.retroarch.ra32",
)
# Where Android keeps each app's private data.
ANDROID_APP_DATA = Path("/data/data")


def _is_android() -> bool:
    """Android reports itself as Linux, so the runtime is named instead.

    Termux inherits the two variables the Android runtime exports, and
    /system/build.prop covers a shell that was started without them.
    """
    if os.environ.get("ANDROID_ROOT") and os.environ.get("ANDROID_DATA"):
        return True
    return Path("/system/build.prop").exists()


def detect_os() -> str:
    """Return normalized OS identifier.

    RETROBIOS_OS names the platform outright (linux, wsl, windows, darwin,
    android), for a run that has to behave like another host: the PowerShell
    wrapper tests drive a Windows layout on a Linux runner.
    """
    forced = os.environ.get("RETROBIOS_OS", "").strip().lower()
    if forced in ("linux", "wsl", "windows", "darwin", "android"):
        return forced
    system = platform.system().lower()
    if system == "linux":
        if _is_android():
            return "android"
        proc_version = Path("/proc/version")
        if _exists(proc_version):
            try:
                content = proc_version.read_text(encoding="utf-8", errors="replace")
                if "microsoft" in content.lower():
                    return "wsl"
            except OSError:
                pass
        return "linux"
    if system == "darwin":
        return "darwin"
    if system == "windows":
        return "windows"
    return system


def _parse_os_release() -> dict[str, str]:
    """Parse /etc/os-release KEY=value format."""
    result: dict[str, str] = {}
    path = _on_device("/etc/os-release")
    if not _exists(path):
        return result
    try:
        for line in path.read_text(encoding="utf-8", errors="replace").splitlines():
            line = line.strip()
            if "=" not in line or line.startswith("#"):
                continue
            key, _, value = line.partition("=")
            value = value.strip('"').strip("'")
            result[key] = value
    except OSError:
        pass
    return result


# Set under WSL: a Windows path read from a config or a rule names a drive
# that Linux sees under /mnt (drvfs). C:\\RetroBat\\bios was used as a relative
# path and nothing Windows-side was ever found from WSL.
# unasked: why Windows could not be asked for its folders, said once by
# detection.
_WSL: dict[str, Any] = {"active": False, "root": "/mnt", "unasked": ""}
_WINDOWS_VARIABLES = ("USERPROFILE", "APPDATA", "LOCALAPPDATA", "ProgramFiles", "ProgramFiles(x86)")


def _host_path(text: str) -> Path:
    """A path as this machine opens it: under WSL, C:\\X is /mnt/c/X."""
    match = re.match(r"^([A-Za-z]):(?:[\\/]+(.*))?$", text) if _WSL["active"] else None
    if match:
        rest = [part for part in re.split(r"[\\/]", match.group(2) or "") if part]
        return Path(_WSL["root"], match.group(1).lower(), *rest)
    return Path(text)


def shown_path(path: Path | str) -> str:
    """A path as the person names it: under WSL, /mnt/d/BIOS is D:\\BIOS, the
    drive the card row calls D:."""
    text = str(spelled(path)) if os.path.isabs(str(path)) else str(path)
    root = _WSL["root"].rstrip("/") + "/"
    match = (re.match(rf"^{re.escape(root)}([a-z])(?:/(.*))?$", text)
             if _WSL["active"] else None)
    if match:
        text = f"{match.group(1).upper()}:\\" + (match.group(2) or "").replace("/", "\\")
    # A folder's name comes from whoever named it: a card's label, a
    # retroarch.cfg, a pack. Printed raw, a control character in it is a
    # terminal command.
    return screen_text(text)


def _wsl_dest(args: argparse.Namespace) -> None:
    """Every path option as WSL opens it: the screen names a card D:, and
    D:\\ given to --dest was refused as a folder that does not exist, then
    E:\\ given to --from once --dest took it."""
    for name in ("dest", "save_dir", "cores_dir"):
        if getattr(args, name, None) is not None:
            setattr(args, name, _host_path(str(getattr(args, name))))
    for name in ("from", "from_pack"):
        if getattr(args, name, None):
            setattr(args, name, [_host_path(str(path)) for path in getattr(args, name)])


def _enter_wsl() -> None:
    """Read Windows paths through drvfs, and the Windows variables detection
    needs, which WSL does not pass to Linux (only those named in WSLENV)."""
    _WSL["active"] = True
    for variable in _WINDOWS_VARIABLES:
        if os.environ.get(variable):
            continue
        try:
            # No stdin: cmd.exe inherited the terminal and swallowed the
            # answer typed at the first prompt.
            result = subprocess.run(
                ["cmd.exe", "/c", f"echo %{variable}%"],
                capture_output=True, text=True, timeout=10, stdin=subprocess.DEVNULL,
                cwd="/mnt/c" if Path("/mnt/c").is_dir() else None,
            )
        except (OSError, subprocess.SubprocessError) as exc:
            # The others would wait as long: detection is told the Windows
            # side was not searched, never that nothing is there.
            _windows_unasked("cmd.exe", exc)
            return
        value = result.stdout.strip()
        if value and not value.startswith("%"):
            os.environ[variable] = str(_host_path(value))


def _windows_unasked(tool: str, exc: Exception) -> None:
    """Keep why a Windows program run from WSL gave no answer: an interop
    slow to start or turned off hid every Windows setup, and the run said
    none was installed."""
    if isinstance(exc, subprocess.TimeoutExpired):
        why = f"{tool} did not answer in {exc.timeout:g} s"
    else:
        why = f"{tool} could not run: {getattr(exc, 'strerror', None) or exc}"
    _WSL["unasked"] = _WSL["unasked"] or why


def _expand_retroarch_path(value: str, app_dir: Path, home: Path | None = None) -> Path:
    """Expand the notations RetroArch writes into its config values.

    fill_pathname_expand_special (libretro-common/file/file_path.c) maps a
    leading '~' to the home directory and a leading ':' to the application
    directory, dropping the two leading characters in both cases.
    """
    if value[:1] == "~":
        return (home or Path(str(Path.home()))) / value[2:]
    if value[:1] == ":":
        return app_dir / value[2:]
    return _host_path(os.path.expandvars(os.path.expanduser(value)))


def _retroarch_cfg_dir(
    cfg_path: Path, key: str, app_dir: Path, default: str, home: Path | None = None
) -> Path | None:
    """A directory setting of retroarch.cfg, as RetroArch expands it.

    A value left empty or at `default` is the directory RetroArch falls back
    on, `default` under app_dir. None when the config is unreadable or does
    not set the key. A config this user cannot read is said once, like a
    closed folder: a retroarch.cfg a `sudo retroarch` left to root hid the
    setup without a word.
    """
    try:
        lines = cfg_path.read_text(encoding="utf-8", errors="replace").splitlines()
    except OSError as exc:
        _note_refused(cfg_path, exc)
        return None
    for line in lines:
        line = line.strip()
        name, sep, value = line.partition("=")
        if sep and name.strip() == key:
            value = value.strip().strip('"').strip("'")
            if not value or value == "default":
                return app_dir / default
            return _expand_retroarch_path(value, app_dir, home)
    return None


def _steam_libraries() -> list[Path]:
    """Every Steam library, the default one first.

    Steam lists the others in steamapps/libraryfolders.vdf, each as a
    "path" line. A RetroArch installed on D:/SteamLibrary was not found
    when only Program Files was searched. The client's own folder is the
    SteamPath value it writes under HKCU\\Software\\Valve\\Steam, read the
    same way by Playnite (PlayniteExtensions 886468f6,
    source/Libraries/SteamLibrary/Steam.cs:34-38): a client installed in
    D:\\Steam hid every library.
    """
    roots: list[Path] = []
    steam_path = _read_registry("HKCU\\Software\\Valve\\Steam", "SteamPath")
    candidates = [_host_path(steam_path.replace("/", "\\"))] if steam_path else []
    for var in ("ProgramFiles(x86)", "ProgramFiles"):
        base = os.environ.get(var, "")
        if base:
            candidates.append(Path(base) / "Steam")
    for candidate in candidates:
        if candidate not in roots and _is_dir(candidate):
            roots.append(candidate)
    libraries = list(roots)
    for root in roots:
        vdf = root / "steamapps" / "libraryfolders.vdf"
        try:
            text = vdf.read_text(encoding="utf-8", errors="replace")
        except OSError:
            continue
        for raw in re.findall(r'"path"\s+"([^"]+)"', text):
            library = Path(raw.replace("\\\\", "\\"))
            if library not in libraries:
                libraries.append(library)
    return libraries


def _windows_retroarch_dirs() -> list[Path]:
    """Folders holding retroarch.exe where its installers put it.

    C:/RetroArch-Win64 by default, C:/RetroArch for 32-bit builds, the same
    names under Program Files, every Steam library, the Emulators folder of
    an installed ES-DE (es_find_rules.xml lists all of them), and a Scoop
    install, user or global.
    """
    candidates = [_host_path("C:/RetroArch-Win64"), _host_path("C:/RetroArch")]
    for var in ("ProgramFiles", "ProgramFiles(x86)"):
        root = os.environ.get(var, "")
        if root:
            candidates += [Path(root) / "RetroArch-Win64", Path(root) / "RetroArch"]
            candidates += [
                Path(root) / "ES-DE" / "Emulators" / name
                for name in ("RetroArch-Win64", "RetroArch")
            ]
    candidates += [
        library / "steamapps" / "common" / "RetroArch" for library in _steam_libraries()
    ]
    # Scoop's Extras bucket: <root>\apps\retroarch\current, the root being
    # %SCOOP% or ~\scoop for a user install, %SCOOP_GLOBAL% or
    # %ProgramData%\scoop for a global one. Its system folder is persisted
    # through a junction, so the folder beside retroarch.exe is the real one.
    scoop_roots = [
        os.environ.get("SCOOP") or (
            str(Path(os.environ["USERPROFILE"]) / "scoop") if os.environ.get("USERPROFILE") else ""
        ),
        os.environ.get("SCOOP_GLOBAL") or (
            str(Path(os.environ["ProgramData"]) / "scoop") if os.environ.get("ProgramData") else ""
        ),
    ]
    candidates += [
        Path(root) / "apps" / "retroarch" / "current" for root in scoop_roots if root
    ]
    return [folder for folder in candidates if _is_file(folder / "retroarch.exe")]


def _macos_retroarch_base() -> Path:
    """Where RetroArch on macOS keeps its system folder by default:
    ~/Documents/RetroArch, or Application Support/RetroArch for a portable
    install. The Steam build is always portable (platform_darwin.m, `#if
    HAVE_STEAM portable = YES`), with no portable.txt to say so: its
    bundle under Steam's library, and no other RetroArch.app, mark it."""
    support = Path.home() / "Library" / "Application Support" / "RetroArch"
    if _is_file(support / "portable.txt"):
        return support
    steam = (
        Path.home() / "Library" / "Application Support" / "Steam" / "steamapps"
        / "common" / "RetroArch" / "RetroArch.app"
    )
    if _is_dir(steam) and not _is_dir(Path("/Applications/RetroArch.app")):
        return support
    return Path.home() / "Documents" / "RetroArch"


def _retroarch_appimage_dirs(home: Path) -> list[Path]:
    """The system folder of each RetroArch AppImage kept with a portable
    folder, up to two folders below home.

    The buildbot's Linux build unpacks RetroArch-Linux-x86_64.AppImage beside
    RetroArch-Linux-x86_64.AppImage.home/.config/retroarch. The AppImage
    runtime sets HOME to <AppImage>.home and XDG_CONFIG_HOME to
    <AppImage>.config when those folders exist (type2-runtime fedfad51,
    src/runtime/runtime.c:1449-1462), so this RetroArch never reads
    ~/.config/retroarch. The archive holds no retroarch.cfg: until the first
    run writes one, the system folder is the base folder's (frontend_unix_get_env
    in platform_unix.c).
    """
    images: list[Path] = []
    for depth in ("", "*/", "*/*/"):
        for suffix in (".home", ".config"):
            try:
                hits = sorted(home.glob(f"{depth}*.AppImage{suffix}"))
            except OSError:
                continue
            for hit in hits:
                image = hit.with_name(hit.name[:-len(suffix)])
                if image not in images and _is_file(image):
                    images.append(image)
    dirs: list[Path] = []
    for image in images:
        portable_home = image.with_name(image.name + ".home")
        portable_config = image.with_name(image.name + ".config")
        if _is_dir(portable_config):
            base = portable_config / "retroarch"
        elif _is_dir(portable_home) and "XDG_CONFIG_HOME" not in os.environ:
            base = portable_home / ".config" / "retroarch"
        else:
            continue
        tilde = portable_home if _is_dir(portable_home) else home
        system = _parse_retroarch_system_dir(base / "retroarch.cfg", base, tilde)
        if system is None and _is_dir(base):
            system = base / "system"
        if system is not None and system not in dirs:
            dirs.append(system)
    return dirs


def _unix_retroarch_base() -> Path:
    """RetroArch's base folder on Linux: $XDG_CONFIG_HOME/retroarch when the
    variable is set, else ~/.config/retroarch (fill_pathname_application_data
    in file_path_special.c, frontend_unix_get_env in platform_unix.c). The
    code tests only that the variable exists, so an empty one counts."""
    xdg = os.environ.get("XDG_CONFIG_HOME")
    if xdg is not None:
        return Path(xdg) / "retroarch"
    return Path.home() / ".config" / "retroarch"


# System directory -> the retroarch.cfg it was read from and the directory
# ':' expands to there, for finding the cores of the same installation.
_RETROARCH_CONFIGS: dict[Path, tuple[Path, Path]] = {}


def _parse_retroarch_system_dir(
    cfg_path: Path, app_dir: Path | None = None, home: Path | None = None
) -> Path | None:
    """Parse system_directory from retroarch.cfg.

    app_dir is RetroArch's application directory, used to expand ':' values.
    It defaults to the directory holding the config, which is where a portable
    install keeps both. home is what '~' means to that RetroArch, the user's
    home when not given.
    """
    if not _exists(cfg_path):
        return None
    app_dir = app_dir or cfg_path.parent
    system_dir = _retroarch_cfg_dir(cfg_path, "system_directory", app_dir, "system", home)
    if system_dir is not None:
        _RETROARCH_CONFIGS.setdefault(system_dir, (cfg_path, app_dir))
    return system_dir


def _shell_unquote(value: str) -> str:
    """Resolve a shell right-hand side into its effective string value.

    Handles concatenated quoted/unquoted segments the way bash does
    (e.g. "/run/media/deck/EmuSD"/Emulation), expands variables in
    double-quoted and unquoted segments, and stops at unquoted
    whitespace or a comment.
    """
    parts: list[str] = []
    i = 0
    n = len(value)
    while i < n:
        c = value[i]
        if c == '"':
            end = value.find('"', i + 1)
            if end == -1:
                parts.append(os.path.expandvars(value[i + 1:]))
                break
            parts.append(os.path.expandvars(value[i + 1:end]))
            i = end + 1
        elif c == "'":
            end = value.find("'", i + 1)
            if end == -1:
                parts.append(value[i + 1:])
                break
            parts.append(value[i + 1:end])
            i = end + 1
        elif c.isspace() or c == "#":
            break
        else:
            end = i
            while end < n and value[end] not in "\"'#" and not value[end].isspace():
                end += 1
            parts.append(os.path.expandvars(value[i:end]))
            i = end
    return os.path.expanduser("".join(parts))


def _parse_bash_var(path: Path, key: str) -> str | None:
    """Extract the effective value of key= from a bash/shell file."""
    if not _exists(path):
        return None
    try:
        for line in path.read_text(encoding="utf-8", errors="replace").splitlines():
            line = line.strip()
            if line.startswith(f"{key}="):
                _, _, value = line.partition("=")
                return _shell_unquote(value)
    except OSError as exc:
        # A settings.sh a sudo EmuDeck run left to root hid the setup.
        _note_refused(path, exc)
    return None


# Where an embedded system names the board it was built for, in the words
# of our target lists: batocera-system.mk writes BATOCERA_SYSTEM_ARCH,
# recalbox-system.mk RECALBOX_SYSTEM_PLATFORM, ROCKNIX's scripts/image puts
# HW_DEVICE in os-release (RK3326, our rk3326). Lakka's scripts/image writes
# LIBREELEC_DEVICE when the image is built for a device (RPi4) and always
# LIBREELEC_PROJECT (Generic): the first one set is the board. KNULLI moves
# /usr/share/batocera to /usr/share/knulli (knulli-linux 57afa662,
# board/scripts/post-build-script.sh:264-278) and writes KNULLI_SYSTEM_ARCH
# to knulli.arch (package/system/knulli-system/knulli-system.mk:98-99).
# AmberELEC's scripts/image writes COREELEC_DEVICE (a21975bf, line 168), the
# DEVICE its Makefile builds (RG351P). EmuELEC's writes the same line (v4.8,
# line 189), the DEVICE of the release image (OdroidGoAdvance).
_BOARD_SOURCES: dict[str, tuple[str, str]] = {
    "amberelec": ("os_release", "COREELEC_DEVICE"),
    "emuelec": ("os_release", "COREELEC_DEVICE"),
    "batocera": ("file", "/usr/share/batocera/batocera.arch"),
    "recalbox": ("file", "/recalbox/recalbox.arch"),
    "rocknix": ("os_release", "HW_DEVICE"),
    "lakka": ("os_release", "LIBREELEC_DEVICE|LIBREELEC_PROJECT"),
    "knulli": ("file", "/usr/share/knulli/knulli.arch"),
    "retropie": ("retropie", ""),
}

# The board a system's own name stands for, where the two differ: the
# target lists are named for the board files (configs/knulli-rk3566.board),
# and the arch file for the TARGET flag the board sets. knulli-rk3566.board
# sets BR2_PACKAGE_BATOCERA_TARGET_RK3568, which knulli-system.mk:22-23
# (20260511) writes as rk3568. batocera-zen3.board sets TARGET_ZEN3, which
# batocera-system.mk:56-57 (batocera-43.1) writes as x86-64-v3.
_BOARD_NAMES: dict[str, dict[str, str]] = {
    "batocera": {"x86-64-v3": "zen3"},
    "knulli": {"rk3568": "rk3566"},
}


# The board a card names on a partition a computer reads. Batocera writes
# its image's board to boot/batocera.board on the BATOCERA boot partition,
# the FAT one beside SHARE (batocera-43.1, board/batocera/scripts/
# post-image-script.sh:60), and reads it there itself (package/batocera/
# core/batocera-scripts/scripts/batocera-info). batocera.arch is inside the
# image, out of a computer's reach. KNULLI writes boot/knulli.board the same
# way (knulli-linux 20260511, board/scripts/post-image-script.sh:66). Both
# write the image's name, which the target list maps to its board.
_CARD_BOARD_FILES: dict[str, str] = {"batocera": "boot/batocera.board",
                                     "knulli": "boot/knulli.board"}


def card_board(platform: str) -> str | None:
    """The board the card mounted here names, None where no card or two
    cards of different boards do: a card is most often prepared on a
    computer, where the system's own board file does not exist."""
    where = _CARD_BOARD_FILES.get(platform)
    if where is None:
        return None
    boards: set[str] = set()
    for mount in _mounted_cards():
        try:
            value = (mount / where).read_text(encoding="utf-8", errors="replace")
        except OSError:
            continue
        if value.strip() and not _CONTROLS.search(value.strip()):
            boards.add(value.strip().lower())
    return boards.pop() if len(boards) == 1 else None


def detect_board(platform: str) -> str | None:
    """The board this system was built for, or None where it names none."""
    kind, where = _BOARD_SOURCES.get(platform, ("", ""))
    if kind == "file":
        try:
            value = Path(where).read_text(encoding="utf-8", errors="replace")
        except OSError:
            return None
    elif kind == "os_release":
        release = _parse_os_release()
        value = next((release[key] for key in where.split("|") if release.get(key)), "")
    elif kind == "retropie":
        value = _retropie_board() or ""
    else:
        return None
    board = value.strip().lower()
    # A board no TARGET line names is written "unknown" (KNULLI's r16).
    if board == "unknown":
        return None
    return _BOARD_NAMES.get(platform, {}).get(board, board) or None


# RetroPie names its board as get_platform does (RetroPie-Setup f5ebfba6,
# scriptmodules/system.sh:396-424 and 425-513): a Pi by the BCM Hardware
# line of /proc/cpuinfo or raspberrypi in its device tree, its model by the
# CPU field (bits 12-15) of a revision code with bit 23 set, rpi1 without
# it. With neither a Hardware line nor a device tree, the machine: x86_64.
# Read only where RetroPie is installed (rootdir /opt/retropie,
# retropie_packages.sh:17): a computer preparing a Pi's card is no Pi.
_RPI_MODELS = {0: "rpi1", 1: "rpi2", 2: "rpi3", 3: "rpi4", 4: "rpi5"}


def _retropie_board() -> str | None:
    """The target RetroPie's own reading of this machine names, or None."""
    if not _is_dir(_on_device("/opt/retropie")):
        return None
    try:
        cpuinfo = _on_device("/proc/cpuinfo").read_text(encoding="utf-8", errors="replace")
    except OSError:
        cpuinfo = ""
    fields = {key.strip(): value.strip() for key, sep, value in
              (line.partition(":") for line in cpuinfo.splitlines()) if sep}
    tree = _on_device("/proc/device-tree/compatible")
    try:
        compatible = tree.read_bytes().decode("ascii", errors="replace")
    except OSError:
        compatible = None
    hardware = fields.get("Hardware", "")
    if hardware.startswith("BCM") or (not hardware and compatible is not None
                                      and "raspberrypi" in compatible):
        try:
            revision = int(fields.get("Revision", ""), 16)
        except ValueError:
            return None
        if not (revision >> 23) & 1:
            return "rpi1"
        return _RPI_MODELS.get((revision >> 12) & 15)
    if hardware or compatible is not None:
        return None
    return "x86_64" if platform.machine() == "x86_64" else None


def _parse_json_path(path: Path, *keys: str) -> str | None:
    """Extract a nested string value from a JSON file."""
    if not _exists(path):
        return None
    try:
        data = json.loads(path.read_text(encoding="utf-8", errors="replace"))
        for key in keys:
            data = data[key]
        return data if isinstance(data, str) and data else None
    except (OSError, json.JSONDecodeError, KeyError, TypeError):
        return None


def _parse_ps1_var(path: Path, key: str) -> str | None:
    """Extract value of $key= or key= from a PowerShell file."""
    if not _exists(path):
        return None
    normalized = key.lstrip("$")
    try:
        raw = path.read_bytes()
        # Windows PowerShell's Out-File writes UTF-16, Set-Content -Encoding
        # UTF8 a byte order mark: EmuDeck's settings.ps1 passes through both.
        encoding = "utf-16" if raw[:2] in (b"\xff\xfe", b"\xfe\xff") else "utf-8-sig"
        for line in raw.decode(encoding, errors="replace").splitlines():
            line = line.strip()
            check = line.lstrip("$")
            if check.startswith(f"{normalized}="):
                _, _, value = check.partition("=")
                return value.strip('"').strip("'")
    except OSError as exc:
        _note_refused(path, exc)
    return None


# The root the embedded rules read under: "/" on a device, a folder holding a
# copy of one in the tests.
_SYSTEM_ROOT = Path("/")


def _on_device(path: str) -> Path:
    """A path of the running system, read under _SYSTEM_ROOT."""
    if _SYSTEM_ROOT == Path("/"):
        return Path(path)
    return _SYSTEM_ROOT / path.lstrip("/")


class _OsRule(NamedTuple):
    """One piece of evidence that names an embedded system.

    manifest is the platform whose files it gets, "" for a system the
    installer does not lay out. name is the system's own name. values are the
    KEY=value pairs of os_release (any one), the files of file_exists (all),
    or the file and the pattern of file_matches. bios is the folder used when
    none of configs (retroarch.cfg files, read in order, `*` allowed) names a
    system_directory. home is what `~` means to that system's RetroArch.
    base is the system this one is built on: both match, this one is meant.
    """

    manifest: str
    name: str
    method: str
    values: tuple[str, ...]
    bios: str | None
    configs: tuple[str, ...] = ()
    home: str = ""
    base: str = ""


# The platform whose files each of these systems gets. They publish their own
# BIOS list, and these platforms transcribe it.
_STANDIN_MANIFESTS = {
    "AmberELEC": "amberelec",
    "EmuELEC": "emuelec",
    "KNULLI": "knulli",
}

