TUI_PAD_ROUTES = tuple(name for name in TUI_ROUTES if name not in ("keys", "both"))
# Set by Steam for what it starts, and by gamescope: a controller may be
# all there is, mapped by Steam Input to keys nobody here can name.
_STEAM_MARKERS = ("SteamGamepadUI", "SteamDeck", "SteamGameId", "GAMESCOPE_WAYLAND_DISPLAY")


# Seconds the interface waits for a first key, no run going, before it
# closes, set by a launcher whose mapper may never open the pad: the screen
# would otherwise hold a handheld that has no other way out.
TUI_IDLE_ENV = "RETROBIOS_IDLE_EXIT"
TUI_IDLE_WORDS = "No button pressed, closing."


def tui_idle_exit(env: Mapping[str, str] | None = None) -> float | None:
    """The seconds RETROBIOS_IDLE_EXIT names, None when unset or not a
    positive number."""
    env = os.environ if env is None else env
    try:
        seconds = float(env.get(TUI_IDLE_ENV, "").strip())
    except ValueError:
        return None
    return seconds if 0 < seconds < float("inf") else None


def tui_pad_route(os_type: str, env: Mapping[str, str] | None = None) -> str:
    """The keys the hints name: a launcher's pad route, "keys" at a desktop,
    "both" (button and key) where nothing says which one is held."""
    env = os.environ if env is None else env
    named = env.get(TUI_PAD_ENV, "").strip().lower()
    if named:
        return named if named in TUI_PAD_ROUTES else "both"
    if any(env.get(name) for name in _STEAM_MARKERS):
        return "both"
    if os_type in ("windows", "darwin", "wsl"):
        return "keys"
    # A Linux console is where a handheld draws: a desktop or a remote
    # shell is a keyboard's.
    if os_type == "linux" and env.get("TERM") != "linux" and any(
            env.get(name) for name in ("DISPLAY", "WAYLAND_DISPLAY", "SSH_CONNECTION",
                                       "SSH_TTY")):
        return "keys"
    return "both"


def _terminal_size(stream: TextIO) -> tuple[int, int]:
    try:
        size = os.get_terminal_size(stream.fileno())
    except (OSError, ValueError, AttributeError, io.UnsupportedOperation):
        return 0, 0
    return size.columns, size.lines


# Where ncurses finds a terminal's compiled description after $TERMINFO,
# ~/.terminfo and $TERMINFO_DIRS.
_TERMINFO_DIRS = ("/etc/terminfo", "/lib/terminfo", "/usr/share/terminfo",
                  "/usr/lib/terminfo", "/usr/share/lib/terminfo")
# cursor_address, string capability 10 of term(5).
_TERMINFO_CUP = 10
# max_colors, numeric capability 13.
_TERMINFO_COLORS = 13


def _terminfo_folders(env: Mapping[str, str]) -> list[Path]:
    folders = [Path(env["TERMINFO"])] if env.get("TERMINFO") else []
    if env.get("HOME"):
        folders.append(Path(env["HOME"]) / ".terminfo")
    # An empty entry stands for the system's folders, which come last anyway.
    folders += [Path(part) for part in env.get("TERMINFO_DIRS", "").split(":") if part]
    return folders + [Path(folder) for folder in _TERMINFO_DIRS]


def _terminfo_header(data: bytes) -> tuple[int, int, int, int, int] | None:
    """Of a compiled term(5) entry: the width of a number, the counts of
    names bytes, booleans, numbers and strings. None when data is none."""
    if len(data) < 12:
        return None
    # The legacy format stores numbers in 2 bytes, the extended one in 4.
    width = {0o432: 2, 0o1036: 4}.get(int.from_bytes(data[0:2], "little", signed=True))
    if width is None:
        return None
    names, bools, numbers, strings = (int.from_bytes(data[at:at + 2], "little", signed=True)
                                      for at in (2, 4, 6, 8))
    return width, names, bools, numbers, strings


def terminfo_number(data: bytes, index: int) -> int | None:
    """Numeric capability index of a compiled term(5) entry, -1 when the
    entry lacks it, None when data is no compiled entry."""
    header = _terminfo_header(data)
    if header is None:
        return None
    width, names, bools, numbers, _strings = header
    if index >= numbers:
        return -1
    start = 12 + names + bools
    start += start % 2 + index * width
    if start + width > len(data):
        return None
    value = int.from_bytes(data[start:start + width], "little", signed=True)
    return value if value >= 0 else -1


def terminfo_string(data: bytes, index: int) -> str | None:
    """String capability index of a compiled term(5) entry, "" when the
    entry lacks it, None when data is no compiled entry."""
    def short(at: int) -> int:
        return int.from_bytes(data[at:at + 2], "little", signed=True)

    header = _terminfo_header(data)
    if header is None:
        return None
    width, names, bools, numbers, strings = header
    offsets = 12 + names + bools
    offsets += offsets % 2 + numbers * width
    if index >= strings:
        return ""
    at = short(offsets + 2 * index)
    if at < 0:
        return ""
    start = offsets + 2 * strings + at
    end = data.find(b"\0", start)
    if end < 0:
        return None
    return data[start:end].decode("latin-1")


def _terminfo_data(term: str, env: Mapping[str, str]) -> bytes | None:
    """TERM's compiled description, the first found, None when none is:
    Windows, Android and many handheld images carry none."""
    if not term or "/" in term or term.startswith("."):
        return None
    for folder in _terminfo_folders(env):
        # Linux files xterm under x/, macOS under 78/.
        for sub in (term[0], f"{ord(term[0]):02x}"):
            try:
                return (folder / sub / term).read_bytes()
            except (OSError, ValueError):
                continue
    return None


def terminal_cursor_address(term: str, env: Mapping[str, str]) -> str | None:
    """How TERM's description here moves the cursor, "" when it cannot,
    None when no description is found, and the screen is not held back
    for it."""
    data = _terminfo_data(term, env)
    return None if data is None else terminfo_string(data, _TERMINFO_CUP)


def terminal_colours(term: str, env: Mapping[str, str]) -> int | None:
    """The colours TERM's description here names, 0 when it names none
    (vt100), None when no description is found or it cannot be read."""
    data = _terminfo_data(term, env)
    if data is None:
        return None
    count = terminfo_number(data, _TERMINFO_COLORS)
    return None if count is None else max(count, 0)


def terminal_few_colours(env: Mapping[str, str]) -> str:
    """Why TERM's description here leaves colour off, "" when it does not:
    no description is no refusal, as for the cursor."""
    if os.name == "nt":
        return ""
    term = env.get("TERM", "")
    count = terminal_colours(term, env)
    if count is not None and count < 8:
        return f"TERM={term} names {count} colours, fewer than 8"
    return ""


def colour_blocker(env: Mapping[str, str], stream: TextIO) -> str:
    """Why the full-screen interface draws without colour, "" when it paints
    with the roles of COLOUR_ROLES. The text is the same either way."""
    if env.get("NO_COLOR"):
        return "NO_COLOR is set"
    isatty = getattr(stream, "isatty", None)
    if not (isatty and isatty()):
        return "the output is not a terminal"
    if os.name != "nt" and env.get("TERM", "") in ("", "dumb"):
        return "TERM is dumb or not set"
    return terminal_few_colours(env)


def terminal_without_ansi(env: Mapping[str, str]) -> str:
    """Why TERM's description here says the ANSI sequences the screen and
    the progress line write would print as text, "" when it does not."""
    if os.name == "nt":
        return ""
    term = env.get("TERM", "")
    cup = terminal_cursor_address(term, env)
    if cup == "":
        return f"TERM={term} cannot move the cursor"
    if cup is not None and not cup.startswith(("\x1b[", "\x9b")):
        return f"TERM={term} does not take the escape sequences the screen is drawn with"
    return ""


def tui_blocker(
    args: argparse.Namespace, stdin: TextIO | None = None, stdout: TextIO | None = None,
    env: Mapping[str, str] | None = None,
) -> str:
    """Why the full-screen interface cannot run here, "" when it can."""
    env = os.environ if env is None else env
    stdin = stdin or sys.stdin
    stdout = stdout or sys.stdout
    for flag, given in (
        ("--check", args.check), ("--dry-run", args.dry_run),
        ("--list-platforms", args.list_platforms), ("--list-targets", args.list_targets),
        ("--list-systems", args.list_systems), ("--list-cores", args.list_cores),
        ("--list-emulators", args.list_emulators), ("--events", args.events),
        ("--quiet", args.quiet), ("--yes", args.yes), ("--no-input", args.no_input),
        ("--restore", args.restore is not None),
        ("--pack", getattr(args, "pack", None) is not None),
    ):
        if given:
            return f"{flag} runs without questions"
    for name, stream in (("input", stdin), ("output", stdout)):
        isatty = getattr(stream, "isatty", None)
        if not (isatty and isatty()):
            return f"the {name} is not a terminal"
    if os.name != "nt" and env.get("TERM", "") in ("", "dumb"):
        return "TERM is dumb or not set"
    drawing = terminal_without_ansi(env)
    if drawing:
        return drawing
    # A pseudo-terminal nobody sized reports 0x0: script(1) fed from a pipe
    # is one, and the line questions run there as they always have.
    cols, rows = _terminal_size(stdout)
    if cols < TUI_MIN_COLS or rows < TUI_MIN_ROWS:
        return (f"the terminal is {cols}x{rows}, smaller than "
                f"{TUI_MIN_COLS}x{TUI_MIN_ROWS}")
    if os.name == "nt":
        import importlib  # noqa: PLC0415

        try:
            importlib.import_module("msvcrt")
        except ImportError:
            return "this Python has no msvcrt to read keys"
        if not _enable_ansi():
            return "this console does not draw escape sequences (Windows 10 or later does)"
        return ""
    try:
        import termios  # noqa: PLC0415
    except ImportError:
        return "this Python has no termios to read keys"
    try:
        termios.tcgetattr(stdin.fileno())
    except (termios.error, OSError, ValueError, AttributeError,
            io.UnsupportedOperation) as exc:
        return f"single key presses cannot be read here ({exc})"
    return ""


def line_mode_reason(blocker: str, env: Mapping[str, str] | None = None) -> str:
    """Why the questions come line by line, in one line, for a terminal the
    full screen cannot draw on: its size or its TERM. "" for a run that
    asks nothing (--check, a pipe), and for a pseudo-terminal nobody sized
    (script fed from a pipe is 0x0), which is no window."""
    env = os.environ if env is None else env
    small = re.match(r"the terminal is (\d+x\d+), smaller than", blocker)
    if small:
        if "0" in small[1].split("x"):
            return ""
        return (f"The window is {small[1]}: questions come line by line "
                f"({TUI_MIN_COLS}x{TUI_MIN_ROWS} for the full screen).")
    if blocker == "TERM is dumb or not set":
        term = screen_text(env.get("TERM", ""))
        return (f"TERM={term}: questions come line by line." if term
                else "TERM is not set: questions come line by line.")
    if blocker.startswith("TERM="):
        return f"{blocker}: questions come line by line."
    return ""


# TERM values of terminals that report no mouse the xterm way: the Linux
# console (gpm is its own protocol), the DEC VTs and BSD consoles.
_NO_MOUSE_TERMS = ("linux", "vt", "cons", "ansi")


def tui_mouse_blocker(
    stdin: TextIO | None = None, stdout: TextIO | None = None,
    env: Mapping[str, str] | None = None,
) -> str:
    """Why the full screen leaves the mouse to the terminal, "" when it
    asks for clicks. A pad route has no pointer and its mapper may send
    anything a report would be confused with, and RETROBIOS_NO_MOUSE keeps
    the terminal's own selection everywhere."""
    env = os.environ if env is None else env
    stdin = stdin or sys.stdin
    stdout = stdout or sys.stdout
    if _env_on(env, TUI_MOUSE_ENV):
        return f"{TUI_MOUSE_ENV} is set"
    if env.get(TUI_PAD_ENV, "").strip():
        return f"{TUI_PAD_ENV} names a controller route"
    if os.name == "nt":
        # msvcrt.getwch reads keys, never a console mouse record.
        return "a Windows console reports no clicks as keys"
    for name, stream in (("input", stdin), ("output", stdout)):
        isatty = getattr(stream, "isatty", None)
        if not (isatty and isatty()):
            return f"the {name} is not a terminal"
    term = env.get("TERM", "").strip().lower()
    if term in ("", "dumb", "unknown") or term.startswith(_NO_MOUSE_TERMS):
        return f"TERM={term} reports no clicks" if term else "TERM is not set"
    return ""


def tui_wants_mouse(state: TuiState, lines: list[str]) -> bool:
    """Whether the frame takes clicks: not where a command or the result is
    shown, so the terminal's own selection copies it as it always has, nor
    where a path is typed, which a middle or right click pastes into."""
    if state.help:
        return True
    if state.screen == "result":
        # A tap on the bar's Exit closes it, where a touch screen has no
        # Enter: the result is printed again in the terminal once the
        # screen closes, its commands selected there as anywhere.
        return True
    if state.screen in ("command", "path"):
        return False
    # Read from the frame's model: a command wrapped over lines was missed
    # by a match on the drawn text, its URL cut in two.
    return not any(getattr(line, "command", False) for line in lines)


def _tui_system_flags(state: TuiState) -> list[tuple[str, str | None]]:
    """The --system the screen's ticks stand for."""
    needed = {row["system"] for row in state.systems
              if row["missing"] + row["wrong_hash"] > 0}
    if state.systems and not needed <= state.ticked:
        return [("--system", name) for name in sorted(state.ticked)]
    return [("--system", name) for name in state.cli_systems]


def tui_flags(state: TuiState) -> list[tuple[str, str | None]]:
    """The options that carry the choices made on screen, CLI ones included."""
    flags = list(state.passthrough)
    if state.target:
        flags.append(("--target", state.target))
    if state.every_board:
        flags.append(("--every-board", None))
    flags += [("--emulator", name) for name in state.emulators]
    flags += [("--from-pack", str(pack)) for pack in state.packs]
    flags += _tui_system_flags(state)
    flags += [("--core", name) for name in tui_core_flags(state)]
    if state.regions:
        flags.append(("--region", ",".join(state.regions)))
    if state.for_games:
        flags.append(("--for-games", str(state.games_folder) if state.games_folder else None))
        if state.required_only:
            flags.append(("--required-only", None))
    if state.no_game_data:
        flags.append(("--no-game-data", None))
    if state.installed_only and not any(flag == "--cores-dir" for flag, _v in flags):
        flags.append(("--installed-cores", None))
    if state.jobs != 8:
        flags.append(("--jobs", str(state.jobs)))
    flags += state.record_flags
    if (state.record is not None and not state.for_games
            and not any(flag in RECORD_NARROWING for flag, _value in flags)):
        # The whole list, chosen over a recorded narrower one: said so to
        # the runs, whose own reading of the record would narrow it again.
        flags.append(("--all-files", None))
    flags += [("--from", str(folder)) for folder in state.from_folders]
    if (os.environ.get(OFFLINE_VARIABLE) == OFFLINE_FLAG_VALUE
            and not any(flag == "--offline" for flag, _v in flags)):
        # Given as --offline: said so in the command. Set as the variable,
        # the runs inherit it and the words name it.
        flags.append(("--offline", None))
    return flags


_TUI_MODES = {
    "check": ["--check", "--events"],
    "confirm": ["--dry-run", "--events"],
    "preview": ["--dry-run", "--events"],
    "install": ["--events", "--yes"],
}


def tui_argv(state: TuiState, run: str, python: str, script: str) -> list[str]:
    """The child that does what the screen decided."""
    if run in TUI_ACTION_RUNS:
        return tui_action_argv(state, run, python, script)
    # --dest=VALUE: a folder typed as -x would otherwise be read as an option.
    argv = [python, script, f"--platform={state.platform}", f"--dest={state.dest}"]
    if state.manifest_path is not None:
        argv.append(f"--manifest={state.manifest_path}")
    argv += [flag if value is None else f"{flag}={value}" for flag, value in tui_flags(state)]
    if run == "install" and state.add_app and _tui_app_ready(state):
        # Only the install writes: --check and --dry-run refuse it.
        argv.append("--add-app")
    return argv + _TUI_MODES[run]


def tui_run_env(state: TuiState, own_list: bool) -> dict | None:
    """The environment of a child run: None for this one's own, else with
    the markers the run reads (TUI_LIST_ENV, TUI_RECORD_ENV)."""
    marks = {TUI_LIST_ENV: "1"} if own_list else {}
    if tui_record_kept(state):
        marks[TUI_RECORD_ENV] = "1"
    if not marks and TUI_RECORD_ENV not in os.environ:
        return None
    env = {key: value for key, value in os.environ.items() if key != TUI_RECORD_ENV}
    env.update(marks)
    return env


def tui_hint(state: TuiState) -> Invocation:
    """The command the screen's choices make, every option of the run in
    it: what "Same choice without questions" and the sudo advice give."""
    hint = Invocation()
    hint.os_type = state.os_type
    hint.options = ([("--manifest", str(state.manifest_path))]
                    if state.manifest_given and state.manifest_path else [])
    hint.options += tui_flags(state)
    if state.add_app and _tui_app_ready(state):
        hint.options.append(("--add-app", None))
    # The runs inherit the variable, a command shown to the user does not.
    if offline_option(False) and ("--offline", None) not in hint.options:
        hint.options.append(("--offline", None))
    return hint


def tui_command(state: TuiState) -> str:
    """The same choice as one command, in the form the run was started with."""
    return tui_hint(state).command(state.platform, state.dest)


def _tui_card(state: TuiState) -> CardApp | None:
    """The card the BIOS folder is on, read once for each folder."""
    if state.dest is None:
        return None
    if state.card_for != state.dest:
        state.card_for, state.card = state.dest, card_app(state.dest)
    return state.card


def _tui_app_ready(state: TuiState) -> bool:
    """Whether the RetroBIOS app can go on this card: its system has one,
    and the run may use the network to fetch it."""
    card = _tui_card(state)
    return card is not None and card.place is not None and not LOCAL.offline


def _tui_installed(state: TuiState) -> bool:
    """An install that finished with every file in place."""
    summary = state.summary or {}
    return bool(summary) and not summary.get("interrupted") and not summary.get("failed") \
        and state.code == 0


def _app_offer(state: TuiState) -> bool:
    """The result offers the app: the install finished, the card can take
    it, and it was neither asked for nor put already."""
    return (state.screen == "result" and state.app is None and not state.app_running
            and _tui_installed(state) and _tui_app_ready(state))


class TuiRow(NamedTuple):
    """One row a screen lists: what Enter does on it, and what it shows."""

    action: str
    label: str
    right: str = ""
    value: object = None
    style: str = ""
    # Shorter forms of right, longest first, for a narrow screen: the label
    # keeps its room before the right-hand text does.
    narrow: tuple = ()
    # A name cut to the room left when no form of narrow but a count fits:
    # "1 device" named nothing where "TrimUI Smart P..." fits.
    cut: str = ""
    # The right-hand text is never cut: the label is, once its shortest
    # form does not fit beside it (a system's size).
    keep_right: bool = False
    # The column the right-hand text starts at, one for the whole list: the
    # setup list's devices had three right edges at 120 columns.
    align: int = 0


# Screens that scroll text instead of listing rows.
_PAGERS = ("preview", "command", "result", "misplaced", "unreadable", "games", "details")
_CHECKLISTS = ("systems", "cores", "emulators")


def _needed(row: dict) -> int:
    return row["missing"] + row["wrong_hash"]


def _tui_system_label(row: dict, titles: dict | None = None) -> str:
    """The name a person reads: the file list's title when it has one, the
    platform's own name when it is one (Sony - PlayStation), the id with the
    platform's short name otherwise (psx)."""
    title = (titles or {}).get(row["system"])
    if isinstance(title, str) and title.strip():
        return title.strip()
    if row["system"] == OTHER_SYSTEMS:
        return OTHER_TITLE
    name = row.get("name") or row["system"]
    if name == row["system"]:
        return name
    if " " in name or any(char.isupper() for char in name):
        return name
    return f"{row['system']} ({name})"


# What the "other" row of the systems holds, in words (OTHER_SYSTEMS).
OTHER_TITLE = "Other systems and game engines"
OTHER_HELP = ("Other systems and game engines: what cores load for systems this setup "
              "does not list, such as game engines and extra computers.")


def _matches(text: str, needle: str) -> bool:
    return not needle or _folded(needle) in _folded(text)


def _filter_row(state: TuiState) -> TuiRow:
    text = state.filters.get(state.screen, "")
    if state.editing == state.screen:
        return TuiRow("filter", f"Filter: {text}_")
    if text:
        return TuiRow("filter", f"Filter: {text}")
    # A pad has no / and no letters: muxterm's own keyboard types.
    how = {"muxterm": "Select shows a keyboard", "gptokeyb": "with a keyboard",
           "gptokeyb_muxterm": "with a keyboard",
           "evmapy": "with a keyboard", "miyoo": "with a keyboard"}.get(state.pad, "/ to type")
    if state.screen == "platforms":
        # A device name finds its setups: said where it is typed. Plain, as
        # the first screen sends a beginner there.
        return TuiRow("filter", "Filter: setup or device (/)" if how == "/ to type"
                      else f"Filter ({how})")
    return TuiRow("filter", f"Filter ({how})")


def _system_titles(state: TuiState) -> dict:
    titles = (state.manifest or {}).get("system_titles")
    return titles if isinstance(titles, dict) else {}


def _sorted_systems(state: TuiState) -> list[dict]:
    """Systems with something to download first, the ones in place last, each
    group in the order of the names a person reads."""
    titles = _system_titles(state)
    return sorted(state.systems, key=lambda row: (
        _needed(row) == 0, _tui_system_label(row, titles).casefold()))


# Region names as a person writes them, where title case alone is wrong.
_REGION_TITLES = {"asia-ntsc": "Asia (NTSC)", "asia-pal": "Asia (PAL)",
                  "uk": "United Kingdom", WORLD_REGION: "World"}


def region_title(name: str) -> str:
    """north-america as North America, asia-ntsc as Asia (NTSC)."""
    return _REGION_TITLES.get(name) or " ".join(
        word.capitalize() for word in name.split("-"))


def tui_run_files(state: TuiState) -> tuple[list[dict], list[dict]]:
    """The files and omissions the run chooses among, as the check counted
    them: the list without what it set aside before any choice (the save
    entries of a save directory it cannot place), the game data left out
    when the plan leaves it out. Line mode chooses among the same (bare)."""
    manifest = state.manifest or {}
    key = (id(state.manifest), frozenset(state.set_aside or ()), state.no_game_data)
    if state.run_files_cache is not None and state.run_files_cache[0] == key:
        return state.run_files_cache[1]
    aside = state.set_aside or set()
    files = [entry for entry in manifest.get("files") or [] if entry.get("dest") not in aside]
    omitted = list(manifest.get("omitted_files") or [])
    if state.no_game_data:
        files, omitted = leave_out_game_data(files, omitted)[:2]
    state.run_files_cache = (key, (files, omitted))
    return files, omitted


def tui_choices(state: TuiState) -> dict[str, list[str]]:
    """What the run lets one narrow to, read from the files it chooses among."""
    return available_choices(*tui_run_files(state))


def core_ticked(state: TuiState, name: str) -> bool:
    """Whether Cores draws name ticked: every core while none narrows the
    run (state.cores empty), else those chosen."""
    return name in state.cores or (not state.cores and not state.no_cores)


def _core_base(state: TuiState) -> list[str]:
    """The cores a choice on Cores is made among: those of the systems
    chosen, every core the run accepts else (choosable_cores, as line
    mode counts them)."""
    return choosable_cores(*tui_run_files(state), _tui_systems_chosen(state))


def tui_cores_ticked(state: TuiState) -> int:
    """The cores of the systems chosen that are ticked: a core of another
    system ticked counted toward "all cores"."""
    base = _core_base(state)
    if not state.cores:
        return 0 if state.no_cores else len(base)
    return len(set(state.cores) & set(base))


def tui_core_flags(state: TuiState) -> list[str]:
    """The --core the run is given: the cores ticked, none when every core
    of the systems chosen is (the run keeps the same files)."""
    if not state.cores or set(_core_base(state)) <= set(state.cores):
        return []
    return list(state.cores)


def _core_right(size: str | None) -> str:
    """A Cores row's right-hand text: what the core adds, or that it adds
    nothing (line mode's NO_CORE_FILES, in the room of a row)."""
    return size if size and size != NO_CORE_FILES else "no extra file"


def _core_narrow(size: str | None) -> tuple:
    if not size or size == NO_CORE_FILES:
        return ("none",)
    return tuple(form for form in [re.sub(r"^\d+ files?, ", "", size)] if form != size)


def tui_core_sizes(state: TuiState) -> dict[str, str]:
    """What each core adds for the systems chosen, in line mode's words."""
    systems = _tui_systems_chosen(state)
    files = tui_run_files(state)
    key = (id(files), tuple(systems))
    if state.core_sizes_cache is not None and state.core_sizes_cache[0] == key:
        return state.core_sizes_cache[1]
    kept = narrow(*files, systems, [], [])[0] if systems else files[0]
    extra = [entry for entry in kept if entry.get("cores") is not None]
    by_core: dict[str, list[dict]] = {}
    for entry in extra:
        for copy in [entry, *entry.get("alternatives", []), *entry.get("slot_choices", [])]:
            for core in copy.get("cores") or []:
                listed = by_core.setdefault(core, [])
                if not listed or listed[-1] is not entry:
                    listed.append(entry)
    sizes = {core: _core_sized(core_files(held, core))
             for core, held in by_core.items()}
    state.core_sizes_cache = (key, sizes)
    return sizes


def cores_words(chosen: int, total: int) -> str:
    """The cores a run keeps, as the plan, Options and line mode say it:
    all cores, or 3 of 12 cores."""
    return "all cores" if chosen >= total else f"{chosen} of {total} cores"


def core_count_words(cores: list[str], base: list[str]) -> str:
    """cores_words for the cores named out of those the systems chosen
    offer: a core of another system counted toward "all cores", the run
    keeping none of the system's own."""
    return cores_words(len(set(cores) & set(base)), len(base))


def _tui_systems_chosen(state: TuiState) -> list[str]:
    """The systems the run is narrowed to, [] for every system."""
    return [value for _flag, value in _tui_system_flags(state) if value]


def _chosen_cores(state: TuiState) -> set[str] | None:
    """The cores of the systems chosen, None when every system is chosen."""
    if not _tui_systems_chosen(state):
        return None
    return set(_core_base(state))


def tui_systems(state: TuiState) -> list[str]:
    """The systems Choose systems lists for the run, as the check counted
    them (listed_systems): the file list's own count took in a system
    whose only file the run leaves out."""
    if state.choices is not None:
        return state.choices
    return tui_choices(state)["systems"]


def tui_rows(state: TuiState) -> list[TuiRow]:
    """The rows of the current screen, in the order they are shown."""
    screen = state.screen
    if screen in _ACTION_SCREENS:
        return _action_rows(state)
    if screen == "setup":
        # The focused one's folder is spelled out below the list.
        rows = [TuiRow("setup", label, value=index)
                for index, (_plat, _path, label) in enumerate(state.setups)]
        # A drive two systems fit, under each: "Nothing was found here"
        # beside a KNULLI card in the reader.
        rows += [TuiRow("doubt", f"{_mount_name(mount)}: if it is {_doubt_kinds((plat,))}",
                        value=(plat, mount)) for plat, mount in state.doubts]
        return rows + [TuiRow("another", "Another setup or folder")]
    if screen == "platforms":
        return _platform_rows(state)
    if screen == "folder":
        rows = [TuiRow("default", "Use this folder")] if state.folder_default else []
        bound = _tui_card_bound(state)
        if state.folder_kind == "share":
            # The drives mounted here first, each one's bios folder: the
            # share drive of a Batocera card or disk in a reader.
            rows += [TuiRow("share", label, value=folder)
                     for label, folder in share_targets(state.platform)]
        if not bound:
            # The drives mounted here, as line mode numbers them at the same
            # question, each by the BIOS folder its system reads, after the
            # Windows side's usual folder under WSL.
            # The Windows side's folder said missing where it is: taken, the
            # plan said RetroArch reads a folder no RetroArch had.
            # Every row whose folder is missing says so, in both modes: the
            # Windows row alone did.
            drives = [] if state.folder_kind == "share" else [
                TuiRow("drive", label if _is_dir(folder) else _said_with(label,
                                                                         "does not exist yet"),
                       value=folder)
                for label, folder in folder_drives(state.os_type, state.platform,
                                                   state.folder_kind == "usual")]
            return rows + [TuiRow("browse", "Browse for a folder"),
                           TuiRow("type", "Type a path")] + drives
        # Only the cards whose own files say they run the system: A on the
        # first mount wrote Onion's layout on a muOS card.
        mounts = (state.cards if state.cards is not None
                  else mounted_cards_of(bound[0], state.platform))
        cards = [TuiRow("card", f"{_mount_name(mount)} ({_card_what(mount)})", value=mount)
                 for mount in mounts]
        # A drive this system and another both fit is its card, as --dest
        # takes it: "No KNULLI card is mounted" sat beside it.
        doubtful = [mount for mount in doubt_cards(state.platform) if mount not in mounts]
        cards += [TuiRow("card", f"{_mount_name(mount)} (could be "
                         f"{_doubt_kinds(share_doubt(mount)[0])})", value=mount)
                  for mount in doubtful]
        mounts = [*mounts, *doubtful]
        # On the device itself its folder is found, and no card is looked for.
        here = state.folder_default is not None and state.folder_kind == "found"
        blank = [] if here else [
            TuiRow("card", f"{_mount_name(mount)} ({_card_what(mount)})", value=mount)
            for mount in blank_cards_of(bound[0], state.platform) if mount not in mounts]
        rescan = [] if cards or here else [TuiRow("rescan", "Look again")]
        if blank:
            # A blank drive is listed for a system that fills its card when
            # it first starts, after Look again: A never takes a stick.
            return rows + cards + rescan + blank + [TuiRow("browse", "Browse for a folder"),
                                                    TuiRow("type", "Type a path")]
        rows += cards + [TuiRow("browse", "Browse for a folder"), TuiRow("type", "Type a path")]
        return rows + rescan
    if screen == "browse":
        return list(state.browse_rows)
    if screen == "create":
        label = "Create the whole path" if state.facts.get("risky") else "Create it and continue"
        return [TuiRow("create", label), TuiRow("other", "Choose another folder")]
    if screen == "cardroot":
        return [TuiRow("cardroot", "Use the card root"), TuiRow("other", "Choose another folder")]
    if screen == "plan":
        return _plan_rows(state)
    if screen == "systems":
        return _system_rows(state)
    if screen == "options":
        return _option_rows(state)
    if screen == "device":
        return _device_rows(state)
    if screen == "emulators":
        needle = state.filters.get(screen, "")
        return [_filter_row(state)] + [
            TuiRow("emulator", f"[{'x' if name in state.emulators else ' '}] {name}",
                   value=name) for name in tui_emulators(state) if _matches(name, needle)
        ] + _REGIONS_END
    if screen == "regions":
        known = sorted(set(tui_choices(state)["regions"]) | set(state.cli_regions),
                       key=region_title)
        # The order drawn when the screen opened, ranked regions first: a
        # tick moved its row to the top, and the next tap on the same spot
        # ticked the region that slid under the finger.
        # The rank says the order, and the screen opens on it next time.
        order = list(state.region_order or [*state.regions, *(
            name for name in known if name not in state.regions)])
        order += [name for name in [*state.regions, *known] if name not in order]
        ranks = {name: str(rank) for rank, name in enumerate(state.regions, 1)}
        return [TuiRow("region", f"[{ranks.get(name, ' ')}] {region_title(name)}", value=name)
                for name in order] + _REGIONS_END
    if screen == "cores":
        needle = state.filters.get(screen, "")
        # The cores the run accepts (choosable_cores): the whole list's
        # 189 held 8 that read only the save directory the run set aside,
        # and an untick sent them to a run that refused them.
        every = tui_choices(state)["cores"]
        theirs = _chosen_cores(state)
        # The cores of the systems chosen first, the others behind a row:
        # with --system sony-playstation the list opened on a5200 and
        # amiberry, 189 cores long. A core the command
        # line named stays in view.
        shown = every if theirs is None or state.cores_all else [
            name for name in every if name in theirs or name in state.cli_cores]
        sizes = tui_core_sizes(state)
        # Every core ticked when no core narrows the run, as Choose systems
        # ticks every system: all boxes empty read as nothing chosen, and
        # the owner ticked each one by hand. Each with what it adds, as
        # line mode sizes it.
        rows = [_filter_row(state)] + [
            TuiRow("core", f"[{'x' if core_ticked(state, name) else ' '}] {name}",
                   _core_right(sizes.get(name)), name, "" if sizes.get(name) else "dim",
                   _core_narrow(sizes.get(name)), keep_right=bool(sizes.get(name)))
            for name in shown if _matches(name, needle)]
        hidden = len(every) - len(shown)
        if hidden:
            rows.append(TuiRow("morecores", f"Cores of the other systems: {hidden}"))
        return rows + _CHECKLIST_END
    if screen == "confirm":
        if state.running or state.dry is None:
            return []
        if not _needed(state.dry) and not state.dry.get("data_missing"):
            # Counted again, every file is in place: Install wrote nothing
            # and said Done.
            return [TuiRow("close", "Close"), TuiRow("back", "Back")]
        if _offline_only() and not _dry_copies(state):
            # The plan's rule: Install would only fail every file.
            return [TuiRow("back", "Back")]
        return [TuiRow("install", "Install"), TuiRow("back", "Back")]
    if screen == "error":
        rows = ([TuiRow("retry", "Try again")]
                if state.run == "check" and state.error_title
                and state.error_title != TUI_OFFLINE_TITLE else [])
        # Its own verb on the bar: "A/Enter Back" under "Choose another
        # setup or folder".
        return rows + [TuiRow("elsewhere", "Choose another setup or folder")
                       if state.run == "check" else TuiRow("back", "Back"),
                       TuiRow("quit", "Quit")]
    if screen == "quit":
        return [TuiRow("quit", "Quit"), TuiRow("stay", "Stay")]
    if screen == "result" and _app_offer(state):
        # Exit first: the app is put only when it is chosen. Its short
        # form where the whole one does not fit: cut inside "from" at 40
        # columns.
        width = min(state.cols or TUI_MAX_WIDTH, TUI_MAX_WIDTH) - 2
        offer = APP_OFFER if cell_width(f"> {APP_OFFER}") <= width else APP_OFFER_SHORT
        return [TuiRow("exit", "Exit"), TuiRow("addapp", offer)]
    return []


def _emptied_words(state: TuiState) -> str:
    """The plan's headline when no system chosen holds a file under the
    options changed since: "Sega Dreamcast holds only game data"."""
    return emptied_words(state.emptied, state.no_game_data)


def _choice_in_place(state: TuiState) -> str:
    """The plan's headline when every file of the systems ticked is in
    place, while the check counted the whole list: "NEC PC Engine is in
    place", Install offered nothing. "" otherwise."""
    if not state.systems or not state.ticked or not _tui_estimating(state):
        return ""
    chosen = [row for row in state.systems if row["system"] in state.ticked]
    if not chosen or any(_needed(row) for row in chosen) or any(
            event["state"] != "present" for event in _ticked_files(state)):
        return ""
    if _plan_data(state, state.check or {})[0]:
        return ""
    titles = _system_titles(state)
    names = [_tui_system_label(row, titles) for row in chosen]
    subject = (", ".join(names[:-1]) + " and " + names[-1]) if len(names) > 1 else names[0]
    return f"{subject} {'are' if len(names) > 1 else 'is'} in place: nothing is left to install."


def _plan_rows(state: TuiState) -> list[TuiRow]:
    check = state.check or {}
    if (state.emptied and state.systems and not state.ticked) or _choice_in_place(state):
        # The choice emptied by an option: Choose systems first, never an
        # Install that would refuse or take the whole list.
        rows = [TuiRow("systems", TUI_SYSTEMS_ROW)]
        game_data = _game_data_row(state)
        return rows + ([game_data] if game_data is not None else []) + [
            *_details_row(state), TuiRow("options", "Change"), *_more_row(state),
            TuiRow("quit", "Quit")]
    if not (_needed(check) if check else 0) and not check.get("data_missing"):
        return [TuiRow("close", "Close"), *_games_rows(state), *_record_rows(state),
                *_where_rows(state), *_details_row(state), TuiRow("options", "Change"),
                *_more_row(state)]
    # The size the headline says: "Install 6.6 GB" stood under "14930 files
    # to download, 6.8 GB", the copies counted in one and the data files in
    # the other.
    size = _ticked_estimate(state)[1] if _tui_estimating(state) else _plan_fetch(state, check)[1]
    label = (f"{TUI_INSTALL_ROW} {format_size(size)}" if size >= CONFIRM_FROM_BYTES
             else TUI_INSTALL_ROW)
    rows = [TuiRow("install", label)]
    if _offline_only() and not _plan_copies(state, check):
        # Nothing here to copy, and the network refused: Install would
        # only fail every file, in this folder or another.
        rows = []
    files = {event["dest"] for event in state.files}
    if (LOCAL.pack is not None and files and not _plan_copies(state, check)
            and len(_tui_pack_lacks(state, sorted(files))) == len(files)
            and not (check.get("data_missing") and _tui_pack_trees(state))):
        # The pack holds none of them, nor the data files: Install would
        # fail every one.
        rows = []
    if _on_its_card(state) and (state.facts.get("writable") is False
                                or _short_of_space(state, check)):
        # Its system reads this card alone: room is made on it, or it is
        # unlocked, then counted again, first in focus. Install anyway on
        # a mount nobody can write would only fail.
        locked = state.facts.get("writable") is False
        rows = [TuiRow("recheck", "Check again"), TuiRow("folder", "Choose another folder"),
                *([TuiRow("install", "Install anyway")] if rows and not locked else [])]
    elif state.facts.get("writable") is False or _short_of_space(state, check):
        # Every file would fail alike, or the run would stop before the
        # first one: the way out is another folder.
        rows = [TuiRow("folder", "Choose another folder"),
                *([TuiRow("install", "Install anyway")] if rows else [])]
    # --system given: the choice stays offered, the list widened when it is
    # opened. With one system named it was neither shown nor changeable.
    copy = TuiRow("fromcard", "Copy the BIOS files from an old card or a folder")
    if not rows:
        # Nothing can be installed: the remedy the plan names comes first,
        # in focus. Choose systems was, whose systems need the internet
        # too.
        rows.append(copy)
    # Right under Install: the choice the plan opened on, the whole list one
    # press away.
    rows += _games_rows(state)
    rows += _record_rows(state)
    if "systems" in recorded_axes((state.manifest or {}).get("files", [])) and (
            len(state.systems) > 1 or state.cli_systems):
        rows.append(TuiRow("systems", TUI_SYSTEMS_ROW))
    game_data = _game_data_row(state)
    if game_data is not None:
        rows.append(game_data)
    if copy not in rows:
        rows.append(copy)
    if _tui_misplaced(state):
        rows.append(TuiRow("misplaced", "Show the files in the wrong place"))
    if state.unreadable:
        rows.append(TuiRow("unreadable", "Show the files that could not be read"))
    return rows + [*_where_rows(state), *_details_row(state), TuiRow("options", "Change"),
                   *_more_row(state), TuiRow("quit", "Quit")]


# The plan's row to remove files and to see or put back a backup.
TUI_MORE_ROW = TuiRow("more", "More")


def _more_row(state: TuiState) -> list[TuiRow]:
    """More, on every plan: a pack can always be made, and the folder's
    record or backups add removing and putting back."""
    return [TUI_MORE_ROW]


# The plan's row for the record's choice, and the one back to the setups.
TUI_RECORD_ROW = "Same choice as last time"
TUI_WHERE_ROW = TuiRow("where", "Change where")


def _record_rows(state: TuiState) -> list[TuiRow]:
    """Same choice as last time: yes or no, where the folder has a record."""
    if state.record is None or state.cli_choice:
        return []
    day = record_day(state.record)
    label = f"Same choice as on {day}" if day else TUI_RECORD_ROW
    return [TuiRow("record", f"{label}: {_yes(tui_record_kept(state))}")]


def _where_rows(state: TuiState) -> list[TuiRow]:
    """Change where, on a plan opened straight on the one setup found."""
    return [TUI_WHERE_ROW] if state.opened_on_plan and state.stack[:1] == ["setup"] else []


# The plan's explanations, counts and reasons, one press away: a pad has
# no d key.
TUI_DETAILS_ROW = TuiRow("details", "Details")


def _details_row(state: TuiState) -> list[TuiRow]:
    """The Details row, where the plan leaves lines out: --verbose shows
    them all on the plan itself."""
    return [] if tui_verbose(state) else [TUI_DETAILS_ROW]


def games_where(state: TuiState) -> str:
    """Where the games are, as the plan's rows say it."""
    return f"in {state.games_folder.name}" if state.games_folder else "on this card"


def _games_rows(state: TuiState) -> list[TuiRow]:
    """The plan's games rows, for a card that holds games or a run told to
    read them: one press for every file instead, one for only what starts,
    and the games themselves."""
    if not (state.for_games or state.games_here):
        return []
    games = state.games or {}
    count = games.get("games") if state.for_games else None
    rows = [TuiRow("games", f"For the games {games_where(state)}: {_yes(bool(state.for_games))}",
                   _plural(count, "game") if count else "", narrow=(str(count),) if count else ())]
    if state.for_games and count:
        rows.append(TuiRow("startonly", f"Only what starts: {_yes(state.required_only)}"))
    if state.for_games and count:
        rows.append(TuiRow("gameslist", "Show the games"))
    return rows


def games_pager_lines(state: TuiState) -> list[str]:
    """The games read, per system, then those that got every BIOS of their
    system with why: the screen behind Show the games."""
    games = state.games or {}
    lines = [f"{games.get('games', 0)} games in {games.get('folder', '')}, "
             f"{games.get('recognised', 0)} recognised by their content.", ""]
    for row in games.get("found") or []:
        title = system_title(str(row.get("system")), state.manifest)
        regions = ", ".join(region_title(str(r)) for r in row.get("regions") or [])
        lines.append(f"{title} ({row.get('folder')}): {_plural(int(row.get('games', 0)), 'game')}"
                     f", {row.get('recognised', 0)} recognised"
                     + (f", {regions} only" if regions else ", every region"))
    fallback = games.get("fallback") or []
    if fallback:
        lines += ["", "Every BIOS of their system kept, so that they start:"]
        lines += [f"{item.get('name')}: {GAMES_REASONS.get(str(item.get('reason')), '')}"
                  for item in fallback]
    return lines


def games_plan_words(state: TuiState) -> list[str]:
    """What the plan says of the games, under the counts."""
    if not state.for_games:
        return []
    if state.games_unavailable:
        return [f"What the games need is not known: {state.games_unavailable['message']}. "
                "Every file is kept."]
    games = state.games or {}
    if not games:
        return []
    if not games.get("games"):
        return [f"No game found {games_where(state)}: For the games installs nothing."]
    words = []
    narrowed = [f"{system_title(str(row['system']), state.manifest)} "
                f"{', '.join(region_title(str(r)) for r in row['regions'])}"
                for row in games.get("found") or [] if row.get("regions")]
    if narrowed:
        words.append(_detail(f"One region where the games prove it: {'; '.join(narrowed)}."))
    fallback = len(games.get("fallback") or [])
    if fallback:
        words.append(_detail(f"{agree(fallback, 'game gets', 'games get')} every BIOS of "
                             f"{'its' if fallback == 1 else 'their'} system: Show the games."))
    return words


def _tui_categories(state: TuiState) -> dict[str, str]:
    """Each destination's category, from the list the screen holds, for a
    list that marks its game data. The second spellings a folder that keeps
    case installs are in it too: counted as nothing, the result's BIOS and
    game data fell short of its total."""
    manifest = state.manifest or {}
    if not manifest.get("categorized"):
        return {}
    return {str(entry.get("dest")): str(entry.get("category") or "")
            for entry in [*manifest.get("files", []), *manifest.get("case_variants", [])]}


def _tui_tally(state: TuiState, events: Iterable[dict]) -> Tally:
    """The count of file events (dest and size), each with the category the
    list gives its destination: the one count the plan, its game data row
    and the result divide."""
    categories = _tui_categories(state)
    return tally({"size": event["size"], "category": categories.get(event["dest"], "")}
                 for event in events)


def _tui_estimating(state: TuiState) -> bool:
    """Whether the plan counts the systems ticked since the check, not the
    check itself."""
    if not (_choice_line(state) and state.systems and state.check is not None):
        return False
    if _offline_only():
        # Offline the estimate is of the ticks alone: a folder to copy from
        # is counted by the check it starts.
        def ticked(flags: list) -> list:
            return [flag for flag in flags if flag[0] == "--system"]
        return ticked(tui_flags(state)) != ticked(state.checked_flags)
    return True


def _choice_entries(state: TuiState, hidden: bool = False) -> list[dict]:
    """The list's files the choice made keeps, game data included: the
    systems ticked (or named with --system), the cores and the regions, as
    line mode's menu_choice narrows them. The game data row, the save line
    and the data files count these: over the whole list, a plan of one
    system said 5089 game data files and 2.5 GB nothing would install.
    hidden adds the systems ticked that game data left out hides
    (hidden_ticks), whose files the game data row brings back."""
    manifest = state.manifest or {}
    systems = [value for flag, value in tui_flags(state) if flag == "--system" and value]
    if state.emptied and not state.ticked:
        systems = sorted(state.ticked_names)
    elif hidden and systems:
        systems = sorted({*systems, *state.hidden_ticks})
    # The second spellings the check installs, as line mode adds them where
    # the folder keeps case.
    variants = [entry for entry in manifest.get("case_variants") or []
                if entry.get("dest") in state.checked_dests]
    kept = narrow([*(manifest.get("files") or []), *variants], [], systems,
                  list(state.cores), list(state.regions))[0]
    # The check read the list as the run narrows it, --emulator, --target
    # and the installed cores included, and only the systems ticked are
    # left to apply: its files and the game data it left out are that
    # list. Narrowed by the axes alone, the row offered the 8 game data
    # files of every system under a plan for one.
    reached = _checked_scope(state)
    return [entry for entry in kept if entry.get("dest") in reached] if reached else kept


def _checked_scope(state: TuiState) -> set[str]:
    """Every destination the last check read, the game data it left out
    included: the list before the systems are chosen. Empty before a check."""
    left = {dest for group in (state.check_summary or {}).get("left_out") or []
            for dest in group.get("dests") or []}
    return set(state.checked_dests) | left if state.checked_dests or left else set()


def _game_data_row(state: TuiState) -> TuiRow | None:
    """The plan's game data row, one press to leave it out or keep it, for
    a list that marks game data: inside Options alone, it went unseen.

    Counted over the choice, as g at the line menu counts it, kept or left
    out alike, and gone when the choice holds none. --no-game-data given
    has none, as line mode offers no g then: one decision in both modes."""
    if not _tui_categories(state) or state.cli_no_game_data:
        return None
    games = tally(entry for entry in _choice_entries(state, hidden=True)
                  if entry.get("category") == GAME_DATA)
    if not games.games:
        return None
    # The state first, its count after and never cut inside a word: at 40
    # columns "kept, leave out" lost its state.
    sized = f"{_plural(games.games, 'file')}, {format_size(games.game_size)}"
    return TuiRow("gamedata", f"Game data: {'left out' if state.no_game_data else 'kept'}",
                  sized, narrow=(f"{games.games}, {format_size(games.game_size)}",),
                  keep_right=True)


def _offline_only() -> bool:
    """--offline without a pack: what is not on this machine cannot come."""
    return offline_requested() and LOCAL.pack is None


def _plan_copies(state: TuiState, check: dict) -> list[str]:
    """The files to install that this machine holds, by destination."""
    if check is state.dry and check is not state.check:
        return _dry_copies(state)
    local = {event["dest"] for event in state.found} if check is state.check else set()
    sizes = {event["dest"] for event in state.files}
    return [dest for dest in local if dest in sizes]


def _dry_copies(state: TuiState) -> list[str]:
    """The files the confirm or preview run would install that this
    machine holds."""
    local = {event["dest"] for event in state.found}
    return [event["dest"] for event in state.dry_files if event["dest"] in local]


def _short_of_space(state: TuiState, check: dict) -> bool:
    free = state.facts.get("free")
    return free is not None and check.get("bytes_needed", 0) > free


def _system_rows(state: TuiState) -> list[TuiRow]:
    needle = state.filters.get("systems", "")
    titles = _system_titles(state)
    rows = [_filter_row(state)]
    shared = _shared_needed(state)
    for row in _sorted_systems(state):
        label = _tui_system_label(row, titles)
        if not _matches(f"{label} {row['system']}", needle):
            continue
        box = "[x]" if row["system"] in state.ticked else "[ ]"
        need = _needed(row)
        count, size = shared.get(row["system"], (0, 0))
        own, own_size = need - count, row["bytes_needed"] - size
        narrow: tuple = ()
        if not need:
            right = "in place"
        elif not count:
            right = f"{_plural(need, 'file')}, {format_size(row['bytes_needed'])}"
            narrow = (format_size(row["bytes_needed"]),)
        elif not own:
            # Two spellings of shared, never cut: "+ 28 sh." and ", shared"
            # sat beside "+ 1689 shared" on one 40-column screen.
            right = f"{_plural(need, 'file')}, {format_size(size)}, all shared"
            narrow = (f"{format_size(size)}, all shared", format_size(size))
        else:
            right = f"{_plural(own, 'file')}, {format_size(own_size)} + {count} shared"
            narrow = (f"{format_size(own_size)} + {count} shared", format_size(own_size))
        # The size is never rounded to fit: 2.7 KB read 3 KB at 40 columns,
        # beside a total of 2.7 KB. The name is cut instead.
        rows.append(TuiRow("system", f"{box} {label}", right, row["system"],
                           "" if need else "dim", narrow, keep_right=bool(need)))
    return rows + _CHECKLIST_END


# The rows a list of ticks ends on, the same on Choose systems, Cores and
# Preferred regions: below the items, so the focus a list opens on is its
# first item and A there ticks it. All and None sat above the items, and A
# on the None the systems opened on unticked every system. Preferred regions
# has no All: every region ranked in the order drawn is no choice anyone made,
# and none ticked keeps every region.
_CHECKLIST_END = [TuiRow("all", "All"), TuiRow("none", "None"), TuiRow("done", "Done")]
_REGIONS_END = [TuiRow("none", "None"), TuiRow("done", "Done")]


def _first_item(state: TuiState) -> int:
    """The row a list of ticks opens on: its first item. Elsewhere the
    first row that is no heading."""
    rows = tui_rows(state)
    return next((i for i, row in enumerate(rows) if row.action in TUI_TICK_ROWS),
                next((i for i, row in enumerate(rows) if row.action != "heading"), 0))


def _shared_needed(state: TuiState) -> dict[str, tuple[int, int]]:
    """Per system, the files to download that other systems carry too, and
    their size: `3DO 1704 files, 349.0 MB` read as the 3DO BIOS, when 1689
    are the MAME files six systems share. The line mode counts them apart
    the same way (_system_sized)."""
    shared: dict[str, tuple[int, int]] = {}
    for event in state.files:
        if len(event["systems"]) > 1:
            for system in event["systems"]:
                count, size = shared.get(system, (0, 0))
                shared[system] = (count + 1, size + event["size"])
    return shared


def _cores_dir_given(state: TuiState) -> bool:
    return any(flag == "--cores-dir" for flag, _value in state.passthrough)


def _yes(value: bool) -> str:
    return "yes" if value else "no"


# The Change screen's groups, in the order they are drawn: a heading is no
# row Up and Down stop on, and a group with no row is not drawn.
TUI_CHANGE_GROUPS = ("What to install", "Where", "For which device", "How", "See")


def _option_rows(state: TuiState) -> list[TuiRow]:
    """The Change screen: every option one level below the plan, grouped by
    what it decides, each row with its value and its flag."""
    manifest = state.manifest or {}
    choices = tui_choices(state)
    what: list[TuiRow] = []
    if choices["regions"]:
        what.append(TuiRow("regions", "Preferred regions: "
                           + (", ".join(map(region_title, state.regions)) or "any"),
                           "--region"))
    if len(choices["cores"]) > 1:
        # The plan's words, the noun left to the row's own label. A list
        # with one core asks nothing, as line mode does not.
        what.append(TuiRow("cores", "Cores: " + cores_words(
            tui_cores_ticked(state), len(_core_base(state))).replace(" cores", ""), "--core"))
    if "system_cores" in manifest and tui_emulators(state):
        what.append(TuiRow("emulators", f"Emulators: {_emulator_words(state)}",
                           "--emulator"))
    if manifest.get("categorized"):
        # "Leave out game data: no" was a double negative.
        what.append(TuiRow("game_data", "Game data: "
                           + ("left out" if state.no_game_data else "kept"),
                           "--no-game-data"))
    copied = ", ".join(str(folder) for folder in state.from_folders) or "none"
    where = [
        # The plan's folder: AmberELEC's read the games part here and its
        # bios folder on the plan, two values under one name. --dest stays the
        # games part, as the command line takes it.
        TuiRow("folder", "BIOS folder: "
               + _short_path(_plan_folder(state, state.dest), state.home),
               "--dest", style="path"),
    ]
    if manifest.get("save_directory"):
        # The interface said "Name it with --save-dir" and had no row for it.
        where.append(TuiRow("savedir", f"Save folder: {_save_folder_words(state)}",
                            "--save-dir", style="path"))
    where += [TuiRow("from", f"Copy from: {copied}", "--from", style="path"),
              TuiRow("pack", "From a pack: "
                     + (state.packs[0].name if state.packs else "none"), "--from-pack")]
    device: list[TuiRow] = []
    if state.platform in TARGET_PLATFORMS:
        device.append(TuiRow("device", f"Device: {_device_words(state)}", "--target"))
    found = len(state.facts.get("cores", []))
    if _cores_dir_given(state):
        device.append(TuiRow("installed", "Installed cores only: yes, implied by --cores-dir",
                             "--cores-dir"))
    elif state.platform in CORE_PLATFORMS and "system_cores" in manifest and found:
        device.append(TuiRow("installed", f"Installed cores only: "
                             f"{_yes(state.installed_only)} ({found} found)",
                             "--installed-cores"))
    if _tui_app_ready(state):
        device.append(TuiRow("addapp", f"Put RetroBIOS on this card: {_yes(state.add_app)}",
                             "--add-app"))
    # Parallel downloads below: the row goes once nothing is downloaded,
    # and the focus stays on the row just changed.
    how = [TuiRow("offline", "Without the internet: "
                  + ("yes, a pack is read" if LOCAL.pack is not None
                     else _yes(offline_requested())), "--offline")]
    if not LOCAL.offline:
        # From a pack, or offline, nothing is downloaded.
        how.append(TuiRow("jobs", f"Parallel downloads: {state.jobs}", "--jobs"))
    see = [TuiRow("preview", "Preview the file list", "--dry-run"),
           TuiRow("command", "Show the command line")]
    rows: list[TuiRow] = []
    for heading, group in zip(TUI_CHANGE_GROUPS, (what, where, device, how, see)):
        if group:
            rows += [TuiRow("heading", heading, style="head"), *group]
    return rows


def tui_emulators(state: TuiState) -> list[str]:
    """The emulators Emulators lists: each profile once, by the name the
    list gives it, as --list-emulators names them."""
    if state.manifest is None:
        return []
    return sorted(set(emulator_names(state.manifest, *tui_run_files(state)).values()))


def _emulator_words(state: TuiState) -> str:
    """The emulators chosen, as the Change row says them."""
    if not state.emulators:
        return "all"
    if len(state.emulators) <= 2:
        return ", ".join(state.emulators)
    return f"{len(state.emulators)} chosen"


def _board_seen(state: TuiState) -> tuple[str, bool, bool] | None:
    """(board, applied, here) the last check read for this setup and folder."""
    seen = state.board_seen
    if seen is None or seen[:2] != (state.platform, state.dest):
        return None
    return seen[2], seen[3], seen[4]


def _board_where(here: bool) -> str:
    return "this device" if here else "named by the card"


def _device_choice(state: TuiState) -> str:
    """The board the runs install for, "" for every board."""
    if state.every_board:
        return ""
    if state.target:
        return state.target
    seen = _board_seen(state)
    return seen[0] if seen is not None and seen[1] else ""


def _device_words(state: TuiState) -> str:
    """The device as the Change row says it: the board, where the run read
    it when it chose it itself."""
    chosen = _device_choice(state)
    if not chosen:
        return "every board"
    seen = _board_seen(state)
    if not state.target and seen is not None:
        return f"{chosen}, {_board_where(seen[2])}"
    return chosen


def _device_rows(state: TuiState) -> list[TuiRow]:
    """Device: the platform's boards by the names its list gives them, the
    one read here or named by the card first, then every board."""
    targets = state.targets if state.targets_for == state.platform else None
    if not targets:
        return []
    seen = _board_seen(state)
    chosen = _device_choice(state)
    names = sorted(targets)
    if seen is not None and seen[0] in targets:
        names.remove(seen[0])
        names.insert(0, seen[0])
    rows = []
    for name in names:
        images = [str(image) for image in targets[name].get("images") or ()]
        # The device names an image carries say what a board code means.
        right = (_board_where(seen[2]) if seen is not None and name == seen[0]
                 else ", ".join(images))
        narrow = (images[0] + (f" +{len(images) - 1}" if len(images) > 1 else ""),) \
            if images and right != images[0] and name != (seen or ("",))[0] else ()
        rows.append(TuiRow("board", f"({'x' if name == chosen else ' '}) {name}", right,
                           name, narrow=narrow))
    rows.append(TuiRow("board", f"({' ' if chosen else 'x'}) Every board", value=""))
    return rows


def _choose_board(state: TuiState, name: str) -> list[tuple]:
    """A board chosen on Device, back on Change. The board the run reads
    itself is no option: the command stays the one with nothing chosen.
    Every board is always said, the run otherwise reading a board itself
    (one started with --target or --every-board read none)."""
    seen = _board_seen(state)
    read = seen[0] if seen is not None and seen[1] else ""
    state.every_board = not name
    state.target = "" if not name or name == read else name
    return _back(state)


def _save_dir_given(state: TuiState) -> Path | None:
    return next((Path(value) for flag, value in state.passthrough
                 if flag == "--save-dir" and value), None)


def _save_folder_words(state: TuiState) -> str:
    """The frontend's save directory as the Options row shows it."""
    given = _save_dir_given(state)
    if given is not None:
        return _short_path(given, state.home)
    if state.saves and state.saves.get("folder"):
        return _short_path(Path(save_where_words(state.saves["folder"])[1]), state.home)
    place = (save_directory_for(state.dest, state.manifest, None)
             if state.dest is not None and state.manifest else None)
    if isinstance(place, SavePlace):
        return _short_path(spelled(place.directory), state.home)
    return "not known"


def _focus_plan(state: TuiState, action: str) -> None:
    """The plan's focus on the row doing action. A plan that keeps no file,
    a choice emptied or already in place, opens on Choose systems: the
    focus kept its index, and Enter opened Options."""
    actions = [row.action for row in tui_rows(state)]
    keeps_none = _choice_in_place(state) or (state.emptied and state.systems
                                             and not state.ticked)
    if action in actions:
        state.focus["plan"] = actions.index(action)
    elif keeps_none and "systems" in actions:
        state.focus["plan"] = actions.index("systems")


def _push(state: TuiState, screen: str, focus: int = 0) -> list[tuple]:
    state.stack.append(screen)
    state.focus[screen] = focus
    return []


def _replace(state: TuiState, screen: str) -> None:
    state.stack[-1] = screen
    state.focus[screen] = 0


def _back(state: TuiState) -> list[tuple]:
    if state.screen == "packdone" and not state.running and "more" in state.stack:
        # Made or not, its plan is spent: back to More.
        del state.stack[state.stack.index("more") + 1:]
        return []
    if state.screen == "actdone" and not state.running:
        # Done: what was planned is gone, and the plan is counted again.
        return _activate_action(state, TuiRow("recheck", ""))
    effects = [("kill",)] if state.running else []
    if state.running:
        # What the stopped run still reports belongs to no screen.
        state.running = False
        state.run_id += 1
    if len(state.stack) == 1:
        state.stack.append("quit")
        state.focus["quit"] = 0
        return effects
    refused = _none_ticked(state)
    if refused:
        # Done and B leave a list of ticks alike, never with nothing
        # ticked: said on every length of list, in the line the rows
        # leave.
        state.status = refused
        return effects
    chose = state.screen == "systems" and state.ticked != (state.ticked_before or set())
    if state.screen == "systems" and state.widened_from is not None:
        before, state.widened_from = state.widened_from, None
        if state.ticked == {row["system"] for row in before["systems"]}:
            # The systems --system named, ticked again: the exact plan of
            # their own check, not an estimate over every system.
            for field, value in before.items():
                setattr(state, field, value)
            chose = False
    if state.screen == "regions":
        state.region_order = []
    state.stack.pop()
    if chose and state.screen == "plan":
        # The systems chosen, the next press is Install: Back left the focus
        # on Choose systems.
        _focus_plan(state, "install")
    if state.screen == "checking" and not state.running:
        # Stay after Esc on a check started from the command line: a
        # Checking screen nothing feeds counted seconds forever.
        return effects + _start_check(state)
    if state.screen == "plan" and _counts_predate_options(state):
        # The plan's numbers were read under the options before: they are
        # read again, the systems ticked kept.
        return effects + _start_check(state)
    return effects


def _keep_choice(state: TuiState) -> None:
    """The systems ticked, kept for the next check of the same platform's
    list when they are not every system to install: one choice for the
    whole run, whatever is changed on the way (game data, an option, a
    folder, a folder to copy from). A choice already set aside (widening a
    --system) is left as it is."""
    if (state.keep_ticked is not None or not state.systems
            or state.manifest_for != state.platform):
        return
    if state.emptied and not state.ticked:
        # Still the choice the options emptied: the same systems again.
        state.keep_ticked = set(state.ticked_names)
        return
    needed = {row["system"] for row in state.systems if _needed(row)}
    state.keep_ticked = (None if needed <= state.ticked and not state.hidden_ticks
                         else state.ticked | state.hidden_ticks)
    titles = _system_titles(state)
    state.ticked_names = {
        **{name: label for name, label in state.ticked_names.items()
           if name in state.hidden_ticks},
        **{row["system"]: _tui_system_label(row, titles)
           for row in state.systems if row["system"] in state.ticked}}


def tui_quit(state: TuiState, code: int | None = None, asked: bool = True) -> list[tuple]:
    """Leave now: with the install's own code once it ran, else QUIT_CODE
    for a quit the user chose (q, Quit) and 130 for Ctrl-C. asked is a quit
    the user chose, said as one: it read "stopped", the word of an
    interrupted run."""
    state.quit_asked = asked
    if code is None:
        code = QUIT_CODE if asked else 130
    if state.screen == "result":
        code = state.code if state.code is not None else 1
    elif state.screen == "error":
        code = state.error_code
    state.exit_code = code
    return [("kill",)] if state.running else []


def tui_interrupt(state: TuiState) -> list[tuple]:
    """Ctrl-C: an install stops and says what it did, anything else ends."""
    if state.run == "install" and state.running:
        if state.stopping:
            return [("kill",)]
        state.stopping = True
        return [("stop",)]
    return tui_quit(state, asked=False)


def _start_run(state: TuiState, run: str) -> list[tuple]:
    state.run = run
    state.running = True
    state.run_id += 1
    state.started = state.now
    if run == "check":
        # The systems of an earlier check go first: ticks read against them
        # dropped the --system the command line gave.
        state.check, state.files, state.systems, state.reading = None, [], [], None
        state.checked_dests = set()
        state.choices = state.set_aside = None
        state.found, state.scanned, state.unreadable = [], [], []
        state.check_summary = state.saves = None
        state.version = state.version_short = state.board = ""
        state.games = state.games_reading = state.games_unavailable = None
        state.checked_flags = tui_flags(state)
    elif run in ("confirm", "preview"):
        state.dry, state.dry_files, state.dry_summary = None, [], None
        state.dry_saves = None
    else:
        state.done_saves = state.dest_error = None
        state.download = state.progress = state.reading = state.games_reading = None
        state.samples, state.local_dests, state.network = [], {}, 0
        state.finished, state.summary, state.code, state.stopping = [], None, None, False
    return [("run", run)]


def _record_key(options: Iterable[tuple[str, str | None]]) -> list:
    """A choice in a form two spellings of it share: one name per --system
    and --core, in any order."""
    pairs = record_options(record_argv(options))
    return sorted((flag, name.strip()) for flag, value in pairs
                  for name in ((value or "").split(",") if flag in ("--system", "--core")
                               else [value or ""]) if name.strip() or value is None)


def tui_record_kept(state: TuiState) -> bool:
    """Whether the plan's choice is the one the record keeps."""
    if state.record is None:
        return False
    return _record_key(tui_flags(state)) == _record_key(
        record_options(state.record["choice"]))


def _tui_record_take(state: TuiState) -> None:
    """The recorded choice made the screen's, as its options would make it."""
    setup = state.record or {}
    try:
        parsed = build_parser().parse_args(setup.get("choice") or [])
    except SystemExit:
        state.status = "The install record names options this installer lacks, so it is ignored."
        state.record = None
        return
    state.cli_systems = list(parsed.system or [])
    state.cores = [token.strip() for value in parsed.core or [] for token in value.split(",")
                   if token.strip()]
    try:
        state.regions = resolve_regions(parsed.region) if parsed.region else []
    except ValueError:
        state.regions = []
    state.no_game_data = bool(parsed.no_game_data)
    state.installed_only = bool(parsed.installed_cores)
    state.for_games = parsed.for_games is not None
    state.games_folder = parsed.for_games if isinstance(parsed.for_games, Path) else None
    state.required_only = bool(parsed.required_only) and state.for_games
    state.games_choice = "record"
    # Device and Emulators show these: a choice no row showed was kept apart.
    state.target = str(parsed.target or "")
    state.every_board = bool(parsed.every_board)
    state.emulators = list(parsed.emulator or [])
    state.record_flags = [(flag, value) for flag, value in record_options(setup["choice"])
                          if flag == "--declared-only"]


def _tui_record_drop(state: TuiState) -> None:
    """The recorded choice given up: the choice nothing narrows."""
    state.cli_systems, state.cores, state.regions, state.record_flags = [], [], [], []
    state.no_game_data = state.installed_only = state.required_only = False
    state.target, state.every_board, state.emulators = "", False, []
    state.for_games, state.games_folder, state.games_choice = None, None, ""
    # The systems of the recorded check go, and with them its ticks.
    state.systems, state.ticked, state.keep_ticked, state.widened_from = [], set(), None, None


def _tui_record_load(state: TuiState) -> None:
    """Read the record of the setup and folder chosen, once for each, and
    take its choice where nothing chose: the command line, or the screen
    for an earlier folder."""
    key = (state.platform, state.dest)
    if state.dest is None or state.record_for == key:
        return
    taken = tui_record_kept(state)
    state.record_for = key
    setup, path, problem = setup_record(state.platform, state.dest)
    if problem and str(path) not in _RECORD_SAID:
        _RECORD_SAID.add(str(path))
        state.status = f"{problem}, so it is ignored."
    if taken:
        _tui_record_drop(state)
    # Games read on a card are what the plan found, not a choice.
    found = ("--for-games", "--required-only") if state.games_choice in ("", "probe") else ()
    state.record = None
    untouched = not any(flag in RECORD_NARROWING and flag not in found
                        for flag, _value in tui_flags(state))
    state.record = setup
    if setup is not None and not state.cli_choice and untouched:
        _tui_record_take(state)


def _start_check(state: TuiState) -> list[tuple]:
    """Check the chosen folder, after fetching the file list once, the
    systems ticked kept (_keep_choice)."""
    _tui_record_load(state)
    _keep_choice(state)
    _games_look(state)
    state.refocus = ""
    if "plan" in state.stack:
        del state.stack[state.stack.index("plan"):]
    while state.stack and state.stack[-1] in ("checking", "error", "create"):
        state.stack.pop()
    state.stack.append("checking")
    state.facts, state.ticked = {}, set()
    if state.manifest is not None and state.manifest_for == state.platform:
        return _start_run(state, "check")
    state.manifest = None
    state.run, state.run_id = "check", state.run_id + 1
    state.started = state.now
    return [("fetch", state.platform)]


def _games_look(state: TuiState) -> None:
    """For a folder chosen once a card was looked at for games, the new one
    looked at too, from what this run already read (no network): its games
    make "For the games on this card" the choice, unless the user or the
    command line decided."""
    if (state.games_choice in ("user", "cli", "record") or state.games_probed is None
            or state.dest is None or state.games_probed == (state.platform, state.dest)):
        return
    count = games_probe(state.platform, state.dest, network=False, os_type=state.os_type)
    state.games_probed = (state.platform, state.dest)
    state.games_here = count or 0
    state.for_games, state.games_choice = bool(count), "probe"


def _closed_status(state: TuiState, closed: tuple[Path, str]) -> TuiLine:
    folder = _short_path(closed[0], state.home)
    return _styled(f"This user cannot open {folder} ({closed[1]}): choose another folder, "
                   "or give this user access to it.", "refusal")


def _set_platform(state: TuiState, plat: str) -> None:
    """Another setup chosen: its list names other boards and emulators, so
    the ones chosen for the setup before are not carried over."""
    if state.platform and plat != state.platform:
        state.target, state.every_board, state.emulators = "", False, []
        state.targets, state.targets_for, state.targets_problem = None, "", ""
    state.platform = plat


def _known_choice(state: TuiState, plat: str, manifest: dict) -> None:
    """The emulators and the board chosen, kept to those the list now read
    names, the others left out and said in one line: a pack's list can
    lack what the network's held, and the check then failed."""
    names = emulator_names(manifest, manifest.get("files") or [],
                           manifest.get("omitted_files") or [])
    gone = [f"--emulator {name}" for name in state.emulators if name not in names]
    state.emulators = [name for name in state.emulators if name in names]
    boards = state.targets if state.targets_for == plat else None
    if LOCAL.manifest is not None or LOCAL.pack is not None:
        try:
            boards = local_targets(plat)
        except SystemExit:
            # A board list beside the list that is no list: the check says so.
            boards = None
    if state.target and boards is not None and state.target not in boards:
        gone.append(f"--target {state.target}")
        state.target = ""
    if gone:
        state.status = f"Left out, not in this list: {', '.join(gone)}."


def _choose(state: TuiState, plat: str, dest: Path, proposed: bool = False) -> list[tuple]:
    """dest taken for plat. proposed is a folder the installer offered (its
    usual or detected folder, a share drive's bios): created without the
    guard a typed path gets, which Enter on it met as Choose another folder,
    and Enter there brought the same two screens back."""
    state.card_note = ""
    closed = closed_folder(dest)
    if closed is not None:
        # Nothing can be checked or written there: the folder is asked
        # again, on the screen that chose it when it can say why.
        _set_platform(state, plat)
        state.status = _closed_status(state, closed)
        if state.stack and state.screen in ("folder", "browse", "path"):
            return []
        # The folder found here is the one the frontend reads: the built-in
        # default beside it is one it does not, offered as "reads its BIOS
        # files from" and filled with Enter.
        state.folder_default, state.folder_kind = None, "closed"
        return _push(state, "folder")
    card = card_system(dest)
    if card and card[0] == plat and card[1] != dest:
        # A muOS or KNULLI card's root: that system reads a folder below it.
        dest = card[1]
    _set_platform(state, plat)
    state.dest = dest
    if plat in CARD_PLATFORMS and card_platform(dest) is None:
        # The engine refuses a folder inside the card, the list writing
        # Bios/<TAG>/ below the root: the root is offered instead.
        for parent in list(dest.absolute().parents)[:2]:
            holder = card_platform(parent)
            if holder:
                state.facts = {"card_root": parent, "card": holder}
                return _push(state, "cardroot")
    root = _own_card_root(dest)
    if root is not None and not _exists(dest) and _is_dir(dest.parent):
        # The card's own files name it, so its folder is known: created as
        # line mode creates it, and said on the plan, not asked.
        state.card_note = (f"{dest.name} is created on {_mount_name(root)}, where "
                           f"{detected_os(plat, dest) or display_name(plat)} reads it.")
        return _start_check(state)
    if proposed and not _exists(dest):
        # Where no setup is there yet, nothing reads it: said as it is.
        reads = (f", where {detected_os(plat, dest) or display_name(plat)} reads it"
                 if _is_dir(dest.parent) else ", a folder that does not exist yet")
        state.card_note = (f"{dest.name} is created in "
                           f"{_short_path(dest.parent, state.home)}{reads}.")
        return _start_check(state)
    if not dest.exists():
        nearest = _nearest_folder(dest)
        missing = len(dest.absolute().parts) - len(nearest.parts)
        state.facts = {"nearest": nearest, "risky": nearest.parent == nearest or missing > 2}
        # A path whose start was mistyped would be created from the root:
        # the safe answer is the one under A.
        return _push(state, "create", 1 if state.facts["risky"] else 0)
    return _start_check(state)


def _card_folder(state: TuiState, folder: Path) -> CardChoice | None:
    """What a folder chosen for a setup that runs from its SD card resolves
    to, as a card root typed in line mode does: None when no card is asked
    for, on the device itself, whose folder is taken as typed (a KNULLI got
    bios added to it), or when the folder is inside a MinUI card, whose
    root _choose offers."""
    bound = _tui_card_bound(state)
    if bound is None and state.platform:
        # Read as line mode reads a folder typed (ask_platform_folder): a
        # Batocera SHARE drive's root goes to its bios folder, another
        # system's drive is refused, a card's root is said.
        return card_choice(state.platform, state.platform, folder)
    if bound is None or (state.platform in CARD_PLATFORMS and card_root_above(folder)):
        return None
    if state.folder_kind == "found" and state.folder_default is not None:
        return None
    return card_choice(bound[0], state.platform, folder)


def _card_status(state: TuiState, choice: CardChoice, given: bool = False) -> None:
    """Say why a folder is not the card: one short sentence first, which a
    40-column screen shows whole, the folder and what was looked for on it
    after, shown where there is room and in the help. given is a folder
    --dest names, which no choice here can change."""
    if given:
        # --dest is fixed for this run: only another system's card gets
        # "choose another setup". A folder inside a card, or one that is no
        # card, is named again in the command.
        then = (f"Run it again with --dest {shown_path(choice.root)}." if choice.root
                else "--dest names it: choose another setup." if choice.other
                else "Run it again with the card's top folder.")
        short = choice.short or choice.refused + "."
    elif choice.other:
        # The top folder of a card, only another system's: "Choose the
        # card's top folder" sent the user back to the same one.
        bound = _tui_card_bound(state)
        kind = "SHARE drive" if "SHARE drive" in choice.short else "card"
        then = (f"Choose the {display_name(state.platform)} SHARE drive, or go back and "
                f"choose {choice.other}." if kind != "card" and not bound else
                f"Insert the {bound[0] if bound else 'right'} card, or go back and choose "
                f"{choice.other}.")
        short = f"That is {_a(choice.other)} {kind}."
    else:
        then = "Choose the card's top folder."
        short = choice.short or choice.refused + "."
    state.status = _styled(f"{short} {then}", "refusal")
    state.status_more = f"{choice.refused}." + (f" {choice.detail}." if choice.detail else "")


def _card_refusal(state: TuiState, folder: Path) -> bool:
    """Whether folder is refused as the card the chosen setup runs from,
    said in the status when it is."""
    choice = _card_folder(state, folder)
    if choice is None or not choice.refused:
        return False
    _card_status(state, choice)
    return True


def _choose_card(state: TuiState, folder: Path) -> list[tuple]:
    """_choose for a folder picked on the folder, browse or path screen: for
    a setup that runs from its SD card, the card's own BIOS folder, and a
    folder that is not its card refused in words."""
    choice = _card_folder(state, folder)
    if choice is None:
        return _choose(state, state.platform, folder)
    if choice.refused:
        _card_status(state, choice)
        if state.stack and state.screen in ("folder", "browse", "path"):
            return []
        state.folder_default, state.folder_kind = None, "usual"
        return _push(state, "folder")
    return _take_card(state, choice, folder)


def _own_card_root(folder: Path) -> Path | None:
    """The root of the card whose own files name folder as its BIOS folder,
    or None: an Onion card's BIOS, a muOS card's MUOS/bios. No folder above
    a mount point is read, as _card_above reads none: it is another drive."""
    points = _mount_points()
    below = folder
    for parent in list(folder.parents)[:2]:
        if _card_boundary(below, points):
            return None
        below = parent
        card = card_system(parent)
        if card and card[1] == folder:
            return parent
    return None


def _take_card(state: TuiState, choice: CardChoice, root: Path) -> list[tuple]:
    """_choose for the folder card_choice gave root, its note kept on the
    screens up to the plan: --dest, the setup list with --dest and a folder
    picked here said nothing of a stick no file names, where line mode did."""
    card = card_system(root)
    if card and card[1] == choice.folder:
        # Titled as the same card found by itself: "Onion (RetroArch files)".
        _DETECTED_OS.setdefault((choice.plat, choice.folder), card[2])
    elif state.card_bound:
        # A card no file names, chosen as ArkOS's: titled ArkOS, not RetroArch.
        _DETECTED_OS.setdefault((choice.plat, choice.folder), state.card_bound[0])
    # The system's folder below a card that exists is made as line mode
    # makes it (_missing_dest, one level): the screen asked Create the
    # folder? for KNULLI's bios on a blank stick, line mode did not.
    below = choice.folder != root and _is_dir(choice.folder.parent)
    effects = _choose(state, choice.plat, choice.folder, proposed=below)
    # Said once: a note that names the folder already says where the files go.
    named = bool(choice.note) and shown_path(choice.folder) in choice.note
    state.card_note = choice.note if named else " ".join(filter(None, (choice.note,
                                                                       state.card_note)))
    return effects


def _open_folder_screen(state: TuiState, default: Path | None,
                        kind: str = "usual", rebind: bool = False) -> list[tuple]:
    """The folder screen for the chosen setup. rebind is another folder
    asked for from the plan: a card setup found mounted (an Onion card) is
    asked for its card again, never for any folder. A folder off the card
    is one Onion does not read, and the screen said RetroArch."""
    state.folder_default, state.folder_kind = default, kind
    # On the device itself its folder is no card in a reader.
    system = (detected_os(state.platform, state.dest)
              if rebind and dest_drive(state.dest) is not None else "")
    if system and not state.card_bound and card_bound(system, state.platform):
        state.card_bound = card_bound(system, state.platform)
    # The cards are looked for when the screen opens and on Look again: a
    # card inserted meanwhile moved the rows under the focus.
    state.cards = None
    bound = _tui_card_bound(state)
    if bound:
        state.cards = mounted_cards_of(bound[0], state.platform)
    refused = kind == "chosen" and (state.facts.get("writable") is False
                                    or _short_of_space(state, state.check or {}))
    # A folder just refused as full or read-only: Browse, not Use this
    # folder, is under A, or A, A came back to the same warning.
    _push(state, "folder")
    if refused and default is not None:
        state.focus["folder"] = next((index for index, row in enumerate(tui_rows(state))
                                      if row.action == "browse"), 1)
    return []


def _mount_name(mount: Path) -> str:
    """How a person names a mounted card: E:\\ on Windows, its label elsewhere.
    Under WSL /mnt/d is the Windows D: drive, which "d" did not say."""
    if (_WSL["active"] and mount.parent == Path(_WSL["root"]) and len(mount.name) == 1
            and mount.name.isalpha()):
        return f"{mount.name.upper()}:"
    # The label is whoever formatted the card's: shown, never obeyed.
    return screen_text(mount.name or str(mount))


def _mounted_cards() -> list[Path]:
    """Mount points of removable media, where a card or a share appears.

    A handheld's card is most often prepared on a PC with a card reader: on
    Windows every drive but the system one may be that card.
    """
    if os.name == "nt":
        system = os.environ.get("SystemDrive", "C:").upper()
        return [Path(f"{letter}:\\") for letter in "DEFGHIJKLMNOPQRSTUVWXYZ"
                if f"{letter}:" != system and os.path.exists(f"{letter}:\\")]
    found: list[Path] = []
    for root in (Path("/media"), Path("/run/media"), Path("/mnt"), Path("/Volumes")):
        try:
            children = sorted(root.iterdir())
        except OSError:
            continue
        for child in children:
            # WSL's own mounts, and the Windows system drive, hold no card.
            if child.name in ("wsl", "wslg") or (root.name == "mnt" and child.name == "c"):
                continue
            if os.path.ismount(child):
                found.append(child)
            elif root.name in ("media", "run") or root == Path("/run/media"):
                # /media/<user>/<label> and /run/media/<user>/<label>.
                try:
                    found += [g for g in sorted(child.iterdir()) if os.path.ismount(g)]
                except OSError:
                    continue
    return found


def _tui_card_bound(state: TuiState) -> tuple[str, str] | None:
    """The card the chosen setup runs from, when it runs from one."""
    if state.card_bound:
        return state.card_bound
    return card_bound(state.platform, state.platform) if state.platform in CARD_PLATFORMS else None


def _card_what(mount: Path) -> str:
    """What a mounted card is, as its own files say."""
    system = card_system(mount)
    return f"{system[2]} {drive_kind(system)}" if system else "card or drive"


def _browse_rows(folder: Path | None, zips: bool = False,
                 skip: Path | None = None) -> tuple[list[TuiRow], str]:
    """A directory's rows for the browser, cards first, and what went wrong.
    With zips, the ZIP files too: a backup is often one archive. skip is a
    card never offered: the one being installed to, for the copy browser,
    as line mode's Copy from leaves it out."""
    if folder is None:
        drives = [Path(f"{letter}:\\") for letter in "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
                  if os.path.exists(f"{letter}:\\")]
        return [TuiRow("dir", str(drive), value=drive) for drive in drives], ""
    rows = [TuiRow("use", "Use this folder"), TuiRow("up", "..", value=folder.parent)]
    for card in _mounted_cards():
        if card not in (folder, skip):
            # Under WSL by its letter, as every other screen writes D:\BIOS.
            name = _mount_name(card)
            rows.append(TuiRow("dir", f"{name if name.endswith(':') else card} "
                               f"({_card_what(card)})", value=card))
    try:
        entries = list(os.scandir(folder))
    except OSError as exc:
        return rows, f"Cannot open this folder: {exc.strerror or exc}"
    entries.sort(key=lambda entry: (entry.name.startswith("."), entry.name.casefold()))
    rows += [TuiRow("dir", f"{entry.name}/", value=Path(entry.path))
             for entry in entries if entry.is_dir()]
    if zips:
        rows += [TuiRow("zip", entry.name, value=Path(entry.path)) for entry in entries
                 if entry.is_file() and entry.name.lower().endswith(".zip")]
    return rows, ""


# The folders of a system root that hold no one's files: A went into
# /bin from /, the first name in order.
_POSIX_ROOT_SYSTEM = frozenset((
    "bin", "boot", "dev", "efi", "etc", "lib", "lib32", "lib64", "libx32", "lost+found",
    "proc", "root", "run", "sbin", "snap", "srv", "sys", "tmp", "usr", "var",
))
# FILE_ATTRIBUTE_HIDDEN and FILE_ATTRIBUTE_SYSTEM: Explorer shows neither.
_WINDOWS_HIDDEN = 0x2 | 0x4


def _os_folder(path: Path, folder: Path) -> bool:
    """A folder of the system, not one a person keeps files in: the
    recycle bin and restore points of a Windows drive ($RECYCLE.BIN, System
    Volume Information, hidden by Explorer), and /bin, /etc, /usr and the
    like at the root of a Unix system."""
    name = path.name
    if name.startswith(("$", ".")) or name.casefold() == "system volume information":
        return True
    try:
        attributes = getattr(os.stat(path, follow_symlinks=False), "st_file_attributes", 0)
    except OSError:
        attributes = 0
    if attributes & _WINDOWS_HIDDEN:
        return True
    return folder == Path("/") and name in _POSIX_ROOT_SYSTEM


def _browse_to(state: TuiState, folder: Path | None, came_from: Path | None = None) -> None:
    state.browse_dir = folder
    copying = state.browse_for == "from"
    state.browse_rows, state.status = _browse_rows(folder, copying or state.browse_for == "pack",
                                                   _dest_card(state) if copying else None)
    if state.browse_for == "pack":
        # A pack is a ZIP, never a folder.
        state.browse_rows = [row for row in state.browse_rows if row.action != "use"]
    focus = 0
    if (folder is not None and state.browse_for not in ("from", "pack", "packto")
            and folder in (state.home, Path(folder.anchor))):
        # No frontend reads its BIOS files from HOME or a drive's root: A
        # pressed through the screens installed into ~. A goes into a
        # visible subfolder there, never a card or drive listed first (A
        # then took /mnt/d, the Windows D: drive, for the BIOS folder) nor
        # .cache. With none, Use this folder keeps the focus and says where.
        focus = next((index for index, row in enumerate(state.browse_rows)
                      if row.action == "dir" and isinstance(row.value, Path)
                      and row.label == f"{row.value.name}/"
                      and not _os_folder(row.value, folder)), 0)
        if not focus and not state.status:
            state.status = _no_setup_reads(state, folder)
            # Never on the row the sentence warns against: A, A, A put a
            # BizHawk install into the home folder. The first folder below
            # it, hidden ones too, else the folder above.
            focus = next((index for index, row in enumerate(state.browse_rows)
                          if row.action == "dir" and isinstance(row.value, Path)
                          and row.label == f"{row.value.name}/"), 0) or next(
                (index for index, row in enumerate(state.browse_rows)
                 if row.action == "up"), 0)
    if (folder is not None and state.browse_for == "from" and came_from is None
            and folder in (state.home, Path(folder.anchor))):
        # The old card is most often a mounted one: the docs say the copy
        # browser opens on them, and A on Use this folder read all of HOME.
        # Not the card being installed to: it was focused first, and taken.
        mounts = [mount for mount in _mounted_cards() if mount != _dest_card(state)]
        focus = next((index for index, row in enumerate(state.browse_rows)
                      if row.action == "dir" and row.value in mounts), focus)
    for index, row in enumerate(state.browse_rows):
        if came_from is not None and row.action == "dir" and row.value == came_from:
            focus = index
    state.focus["browse"] = focus


def _on_its_card(state: TuiState) -> bool:
    """Whether the BIOS folder is on the SD card of the setup it is for, a
    system that reads that card alone: room is made there, another folder
    being one it never reads."""
    if state.dest is None:
        return False
    return on_its_card(state.platform, state.dest,
                       state.card_bound[0] if state.card_bound else "")


def on_its_card(plat: str, dest: Path, system: str = "") -> bool:
    """Whether dest, a card mounted here, is the SD card of the system it
    is for (system, else the one detection names): line mode and the
    screen say "free some space on the card" alike."""
    system = system or detected_os(plat, dest)
    return bool(system and card_bound(system, plat) and dest_drive(dest) is not None)


def _dest_card(state: TuiState) -> Path | None:
    """The mounted card or drive the BIOS folder is on, None for none."""
    return dest_drive(state.dest)


def dest_drive(dest: Path | None) -> Path | None:
    """The mounted card or drive dest is on, None for none."""
    if dest is None:
        return None
    place = dest.absolute()
    return next((mount for mount in _mounted_cards()
                 if mount == place or mount in place.parents), None)


def copy_source_refusal(chosen: Path | None, dest: Path | None) -> str:
    """Why a folder cannot be copied from, "" when it can: the card being
    installed to, or the BIOS folder itself. The copy browser focused that
    card, and choosing it was taken without a word."""
    if chosen is None or dest is None:
        return ""
    place = chosen.absolute()
    if place == dest.absolute():
        return "That is the BIOS folder being installed to: choose the old card or a backup."
    if place == dest_drive(dest):
        return "That is the card being installed to: choose the old card or a backup."
    return ""


def _no_setup_reads(state: TuiState, folder: Path | None) -> str:
    """Why folder is no BIOS folder, "" when it may be one: no frontend
    reads its BIOS files in the home folder or at a drive's root."""
    if folder is None:
        return ""
    if folder == state.home:
        return "No setup reads BIOS files in the home folder."
    if folder == Path(folder.anchor):
        return "No setup reads BIOS files at a drive's root."
    return ""


def _nearest_folder(path: Path) -> Path:
    """The deepest folder on path that exists and can be looked at."""
    probe = path.absolute()
    while not _is_dir(probe) and probe.parent != probe:
        probe = probe.parent
    return probe


def typed_path(text: str) -> Path | None:
    """A folder typed or pasted: quotes off, ~ and variables expanded."""
    # Explorer's "Copy as path" quotes both ends, a half-selected copy one.
    text = text.strip().strip("\"'").strip()
    if not text:
        return None
    return _host_path(os.path.expanduser(os.path.expandvars(text)))


def _tui_folder_facts(state: TuiState) -> dict:
    """Free space, whether the folder takes files, and the cores found."""
    probe = _nearest_folder(state.dest)
    try:
        free: int | None = shutil.disk_usage(probe).free
    except OSError:
        free = None
    cores = (installed_cores(core_dirs(state.platform, state.dest))
             if state.platform in CORE_PLATFORMS else [])
    return {"free": free, "writable": _folder_writable(state.dest), "cores": cores}


def _activate(state: TuiState, row: TuiRow) -> list[tuple]:
    screen, action = state.screen, row.action
    if action == "details":
        return _open_details(state)
    if action == "filter":
        only = _only_match(state)
        if only is not None:
            # One setup matches: A chooses it, a second press found nothing
            # more to do.
            return _activate(state, only)
        state.editing = screen
        return []
    if screen in _ACTION_SCREENS:
        return _activate_action(state, row)
    if screen == "setup":
        if action == "another":
            return _push(state, "platforms", _platform_focus(state, "retroarch"))
        if action == "doubt":
            # Taken as the system chosen, as --platform with --dest takes it.
            plat, mount = row.value
            state.card_bound = card_bound(plat, plat)
            _set_platform(state, plat)
            choice = card_choice(plat, plat, mount)
            if choice.refused:
                _card_status(state, choice)
                return []
            return _take_card(state, choice, mount)
        plat, path, _label = state.setups[row.value]
        # A setup found here is its folder: a card looked at and backed
        # out of described the RetroArch chosen next as that card.
        state.card_bound = None
        return _choose(state, plat, path, proposed=True)
    if screen == "platforms":
        plat, system = row.value if action == "cardsystem" else (row.value, row.value)
        _set_platform(state, plat)
        state.card_bound = card_bound(system, plat)
        if state.dest_given is not None:
            # Read as --platform with --dest reads it, for the same folder:
            # ROCKNIX's row added roms/bios to a --dest the line mode kept.
            choice = card_choice(system, plat, state.dest_given)
            if choice.refused:
                _card_status(state, choice, given=True)
                state.platform, state.card_bound = "", None
                return []
            return _take_card(state, choice, state.dest_given)
        return _open_folder_screen(state, *setup_folder(
            state.os_type, state.setups, state.mounted_setups, plat, system))
    if screen == "folder":
        if action == "default":
            return _choose(state, state.platform, state.folder_default, proposed=True)
        if action in ("share", "drive"):
            return _choose(state, state.platform, row.value, proposed=True)
        if action in ("card", "rescan"):
            if action == "rescan":
                state.cards = mounted_cards_of(_tui_card_bound(state)[0], state.platform)
                cards = [index for index, item in enumerate(tui_rows(state))
                         if item.action == "card" and item.value in state.cards]
                state.focus["folder"] = cards[0] if cards else state.focus.get("folder", 0)
                state.status = ("" if cards else f"Still no {_tui_card_bound(state)[0]} card "
                                "is mounted.")
                return []
            return _choose_card(state, row.value)
        if action == "browse":
            state.browse_for = "dest"
            _push(state, "browse")
            _browse_to(state, _nearest_folder(state.folder_default or state.home))
            if _tui_card_bound(state) and state.folder_kind != "found":
                # A card is asked for: the drives come first, and the home
                # folder's "go back to type a path" sent the user away from
                # the cards listed under it.
                # Its own cards first: the muOS card listed first was focused
                # for Onion.
                bound = _tui_card_bound(state)
                own = mounted_cards_of(bound[0], state.platform)
                setup = card_setup(bound[0], state.platform)
                # Another system's card is never focused for this one: the
                # muOS card was, under "Choose the Onion card below".
                free = [mount for mount in _mounted_cards()
                        if setup is None or _card_is(setup, mount)[0] != "other"]
                drives = ([index for index, item in enumerate(state.browse_rows)
                           if item.action == "dir" and item.value in own]
                          or [index for index, item in enumerate(state.browse_rows)
                              if item.action == "dir" and item.value in free])
                if drives:
                    state.focus["browse"] = drives[0]
                state.status = (f"Choose the {bound[0]} card below." if own
                                else f"No {bound[0]} card is mounted: insert it, or open "
                                "its top folder.")
            return []
        state.path_text = str(state.folder_default or "")
        state.path_selected = bool(state.path_text)
        return _push(state, "path")
    if screen == "browse":
        if action == "zip" and state.browse_for == "pack":
            # Opened in this process (perform), which answers pack_opened.
            return [("pack", row.value)]
        if action == "use" and state.browse_for == "packto":
            state.pack_dir = state.browse_dir
            state.browse_for = "dest"
            state.stack.pop()
            state.pack_plan = None
            return _start_run(state, "pack_plan")
        if action == "use" and state.browse_for == "save":
            state.passthrough = [flag for flag in state.passthrough
                                 if flag[0] != "--save-dir"]
            state.passthrough.append(("--save-dir", str(state.browse_dir)))
            state.browse_for = "dest"
            return _start_check(state)
        if action in ("use", "zip") and state.browse_for == "from":
            chosen = state.browse_dir if action == "use" else row.value
            refused = copy_source_refusal(chosen, state.dest)
            if refused:
                state.status = _styled(refused, "refusal")
                return []
            if chosen not in state.from_folders:
                state.from_folders.append(chosen)
            state.browse_for = "dest"
            # The check runs again with it: the plan then says what it holds.
            return _start_check(state)
        if action == "use":
            return _choose_card(state, state.browse_dir)
        if action == "up" and state.browse_dir is not None:
            if row.value == state.browse_dir:
                _browse_to(state, None if os.name == "nt" else state.browse_dir)
            else:
                _browse_to(state, row.value, came_from=state.browse_dir)
            return []
        _browse_to(state, row.value)
        return []
    if screen == "create":
        if action == "create":
            state.stack.pop()
            return _start_check(state)
        if len(state.stack) == 1:
            # The folder came from --dest: nothing is under this screen, and
            # Back asked Quit? with Quit in focus. The
            # folder screen takes its place, as the plan's row opens it.
            state.stack.pop()
            return _open_folder_screen(state, state.dest, "chosen", rebind=True)
        return _back(state)
    if screen == "cardroot":
        if action == "cardroot":
            state.stack.pop()
            return _choose(state, state.platform, state.facts["card_root"])
        return _back(state)
    if screen == "plan":
        if action == "install":
            return _begin_install(state)
        if action == "close":
            state.exit_code = 0
            return []
        if action == "quit":
            return tui_quit(state)
        if action == "folder":
            return _open_folder_screen(state, state.dest, "chosen", rebind=True)
        if action == "fromcard":
            return _open_from_browser(state)
        if action in ("misplaced", "unreadable", "more"):
            return _push(state, action)
        if action == "recheck":
            return _start_check(state)
        if action == "where":
            effects = [("kill",)] if state.running else []
            state.running, state.run_id = False, state.run_id + 1
            del state.stack[1:]
            return effects
        if action == "record":
            # No: the choice nothing narrows, the card's games when it holds
            # some. Yes: the recorded choice again. Counted again either way.
            if tui_record_kept(state):
                _tui_record_drop(state)
                if state.dest is not None:
                    count = games_probe(state.platform, state.dest, network=False,
                                        os_type=state.os_type)
                    state.games_probed = (state.platform, state.dest)
                    state.games_here = count or 0
                    state.for_games, state.games_choice = bool(count), "probe"
            else:
                _tui_record_drop(state)
                _tui_record_take(state)
            effects = _start_check(state)
            state.refocus = "record"
            return effects
        if action in ("games", "startonly"):
            # One press, then counted again: the games decide the systems,
            # so the ticks start again from every system they need.
            if action == "games":
                state.for_games, state.games_choice = not state.for_games, "user"
            else:
                state.required_only = not state.required_only
            state.ticked = {row["system"] for row in state.systems if _needed(row)}
            state.hidden_ticks = set()
            effects = _start_check(state)
            state.refocus = action
            return effects
        if action == "gameslist":
            return _push(state, "games")
        if action == "gamedata":
            # One press, then counted again, as Back from Options counts,
            # the systems ticked kept: the check set them back to every
            # system, and the install wrote all eight.
            state.no_game_data = not state.no_game_data
            effects = _start_check(state)
            state.refocus = "gamedata"
            return effects
        if action == "systems" and state.cli_systems:
            # The check read only what --system named: it is read again for
            # every system, those named ticked. Its exact plan is kept, to
            # come back to when the ticks do not change (_back).
            state.widened_from = {field: getattr(state, field) for field in _CHECK_FIELDS}
            state.keep_ticked = {row["system"] for row in state.systems}
            state.cli_systems, state.widen = [], True
            return _start_check(state)
        if action == "systems":
            state.ticked_before = set(state.ticked)
        # On the first system, A ticking it: Choose systems opened on None,
        # and A there unticked every system.
        _push(state, action)
        state.focus[action] = _first_item(state)
        return []
    if screen in (*_CHECKLISTS, "regions"):
        return _checklist(state, row)
    if screen == "options":
        return _option(state, action, 0)
    if screen == "device" and action == "board":
        return _choose_board(state, str(row.value))
    if screen == "confirm":
        if action == "install":
            state.stack.pop()
            return _install_now(state)
        if action == "close":
            state.exit_code = 0
            return []
        return _back(state)
    if screen == "error":
        if action == "retry":
            return _start_check(state)
        if action == "quit":
            return tui_quit(state, state.error_code)
        return _back(state)
    if screen == "quit":
        if action == "quit":
            return tui_quit(state)
        return _back(state)
    if screen == "result":
        if action == "addapp":
            state.add_app = state.app_running = True
            return [("app", _tui_card(state))]
        return tui_quit(state)
    return []


def _checklist(state: TuiState, row: TuiRow) -> list[tuple]:
    """A and Enter on Choose systems, Cores and Preferred regions, one rule
    for the three: an item is ticked or unticked, All and None set every
    box, Done leaves as B does (_back), refused while nothing is ticked."""
    screen, action = state.screen, row.action
    if action == "done":
        return _back(state)
    if action == "morecores":
        state.cores_all = True
        return []
    if action == "region":
        _toggle_region(state, row.value)
    elif action in TUI_TICK_ROWS:
        _tick(state, row, None)
    elif action == "all" and screen == "systems":
        state.ticked = {item["system"] for item in state.systems}
    elif action == "all":
        state.cores, state.no_cores = [], False
    elif action == "none" and screen == "regions":
        state.regions = []
    elif action == "none" and screen == "emulators":
        # None ticked installs for every emulator, as Preferred regions keeps
        # every region with none ticked.
        state.emulators = []
    elif action == "none":
        if screen == "systems":
            state.ticked = set()
        else:
            state.cores, state.no_cores = [], True
        # On the first item: the next A ticks the one in focus alone.
        state.focus[screen] = _first_item(state)
    return []


def _none_ticked(state: TuiState) -> str:
    """Why Done is refused on a list of ticks, "" when it is not."""
    if state.screen == "systems" and state.systems and not state.ticked:
        return "No system is ticked: tick one, or choose All."
    if state.screen == "cores" and state.no_cores:
        return "No core is ticked: tick one, or choose All."
    return ""


def _systems_reading() -> dict[str, list[str]]:
    """The device systems that get each platform's files, as detection knows
    them: someone on muOS or ArkOS looks for that name, not RetroArch."""
    names: dict[str, list[str]] = {}
    for rule in _EMBEDDED_RULES:
        if (rule.manifest and rule.name != display_name(rule.manifest)
                and rule.name not in names.setdefault(rule.manifest, [])):
            names[rule.manifest].append(rule.name)
    return names


